window.AtlasChapters=(window.AtlasChapters||[]).concat([{"id":1,"title":"1단계 — 영어 문장이란?","html":"\u003cp>맞다. \u003cstrong>주제별 문법 설명이 아니라, 선수지식이 다음 문법의 기반이 되도록 순서를 설계해야 한다.\u003c/strong> 처음부터 다시 간다.\u003c/p>\n\u003cp>진행 기준은 \u003cstrong>CEFR의 Pre-A1→A1 기초 단계\u003c/strong>를 뼈대로 하고, 문법 하나를 배울 때는 British Council의 문법 교수 원칙처럼 \u003cstrong>의미(Meaning) → 형태(Form) → 실제 사용(Use) → 통제 연습 → 자유 사용 → 누적 복습\u003c/strong> 순으로 진행하겠다. CEFR도 학습목표·수업·평가가 일관되게 연결되는 것을 중요하게 본다. British Council 역시 문법의 form/use/meaning을 명확히 다루고, 통제 연습에서 자유로운 사용으로 확장하며 이미 배운 내용을 다시 recycling하는 방식을 제시한다.\u003c/p>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">전체 학습의 큰 흐름\u003c/h2>\n\u003cp>앞으로 \u003cstrong>이 순서를 건너뛰지 않는다.\u003c/strong>\u003c/p>\n\u003col>\n\u003cli>\u003cstrong>문장의 기본 구조\u003c/strong> — 주어 + 동사\u003c/li>\n\u003cli>\u003cstrong>be동사\u003c/strong> — am / is / are\u003c/li>\n\u003cli>\u003cstrong>일반동사\u003c/strong> — eat / like / go / have\u003c/li>\n\u003cli>\u003cstrong>인칭대명사\u003c/strong> — I / you / he / she / it / we / they\u003c/li>\n\u003cli>\u003cstrong>부정문\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>의문문\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>명사와 관사\u003c/strong> — a / an / the\u003c/li>\n\u003cli>\u003cstrong>단수·복수\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>가산·불가산 명사\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>형용사\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>부사\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>현재시제\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>과거시제\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>미래 표현\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>진행형\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>조동사\u003c/strong> — can / should / must 등\u003c/li>\n\u003cli>\u003cstrong>비교급·최상급\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>전치사\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>to부정사\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>동명사\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>접속사와 절\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>현재완료\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>수동태\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>관계대명사\u003c/strong>\u003c/li>\n\u003cli>\u003cstrong>조건문\u003c/strong>\u003c/li>\n\u003cli>이후 중급 문법\u003c/li>\n\u003c/ol>\n\u003cp>\u003ccode>가산/불가산\u003c/code>은 이 큰 흐름의 \u003cstrong>9번째 주제\u003c/strong>이며, 이 교재에서는 \u003cstrong>11단계\u003c/strong>에서 다룬다. 처음부터 그걸 설명한 게 순서상 잘못이었다.\u003c/p>\n\u003chr>\n\u003ch1 id=\"lesson-title\" data-id=\"1\">1단계 — 영어 문장이란?\u003c/h1>\n\u003cp>오늘은 이것 하나만 확실하게 잡는다.\u003c/p>\n\u003cp>영어 문장의 가장 작은 뼈대는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사\u003c/strong>\u003cbr>\u003cstrong>Subject + Verb\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">I run.\u003c/h3>\n\u003cul>\n\u003cli>\u003ccode>I\u003c/code> = 주어\u003c/li>\n\u003cli>\u003ccode>run\u003c/code> = 동사\u003c/li>\n\u003c/ul>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 달린다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">Birds fly.\u003c/h3>\n\u003cul>\n\u003cli>\u003ccode>Birds\u003c/code> = 주어\u003c/li>\n\u003cli>\u003ccode>fly\u003c/code> = 동사\u003c/li>\n\u003c/ul>\n\u003cblockquote>\n\u003cp>새들은 난다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">주어란?\u003c/h2>\n\u003cp>\u003cstrong>누가 / 무엇이 행동하거나 어떤 상태에 있는지\u003c/strong>를 나타낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I\u003c/strong> run.\u003cbr>\u003cstrong>She\u003c/strong> smiles.\u003cbr>\u003cstrong>Narin\u003c/strong> sleeps.\u003cbr>\u003cstrong>The dog\u003c/strong> runs.\u003c/p>\n\u003c/blockquote>\n\u003cp>굵은 부분이 전부 \u003cstrong>주어\u003c/strong>다.\u003c/p>\n\u003cp>주어는 꼭 \u003ccode>I\u003c/code>, \u003ccode>you\u003c/code>, \u003ccode>he\u003c/code> 같은 한 단어일 필요는 없다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>The little dog\u003c/strong> runs.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>The little dog\u003c/code> 전체가 주어다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">동사란?\u003c/h2>\n\u003cp>문장에서 \u003cstrong>행동이나 상태를 담당하는 핵심 요소\u003c/strong>다.\u003c/p>\n\u003cp>행동:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>eat\u003c/strong>.\u003cbr>나는 먹는다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>runs\u003c/strong>.\u003cbr>그녀는 달린다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They \u003cstrong>sleep\u003c/strong>.\u003cbr>그들은 잔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>영어에서는 기본적으로 \u003cstrong>완전한 문장을 만들려면 동사가 필요하다.\u003c/strong>\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>I.\u003c/p>\n\u003c/blockquote>\n\u003cp>는 그냥 \u003cstrong>나\u003c/strong>일 뿐이다.\u003c/p>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>I run.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 되면\u003c/p>\n\u003cblockquote>\n\u003cp>나는 달린다.\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 문장이 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">한국어와 가장 먼저 다른 점\u003c/h2>\n\u003cp>한국어:\u003c/p>\n\u003cblockquote>\n\u003cp>나 밥 먹어.\u003cbr>나 피곤해.\u003cbr>예뻐.\u003cbr>비 와.\u003c/p>\n\u003c/blockquote>\n\u003cp>한국어는 문맥에 따라 주어를 자주 생략한다.\u003c/p>\n\u003cp>영어는 기본적으로 주어를 표시한다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I\u003c/strong> am tired.\u003cbr>\u003cstrong>It\u003c/strong> is pretty.\u003cbr>\u003cstrong>It\u003c/strong> is raining.\u003c/p>\n\u003c/blockquote>\n\u003cp>이 차이가 앞으로 영어 문장을 만드는 데 아주 중요하다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">오늘 배울 것은 딱 이것이다.\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>영어 문장의 뼈대 = 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>아직 \u003ccode>목적어\u003c/code>, \u003ccode>보어\u003c/code>, \u003ccode>be동사\u003c/code>, \u003ccode>a/an\u003c/code>, \u003ccode>3인칭 단수\u003c/code>는 배우지 않는다.\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">1단계 연습\u003c/h3>\n\u003cp>다음 문장에서 \u003cstrong>주어와 동사만\u003c/strong> 찾아봐.\u003c/p>\n\u003cp>\u003cstrong>① I run.\u003c/strong>\u003cbr>\u003cstrong>② She smiles.\u003c/strong>\u003cbr>\u003cstrong>③ Dogs bark.\u003c/strong>\u003cbr>\u003cstrong>④ My daughter sleeps.\u003c/strong>\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>① 주어: I / 동사: run\u003c/p>\n\u003c/blockquote>\n\u003cp>이런 식으로 ②~④를 해봐.\u003c/p>\n","toc":[{"id":"reading-1","label":"전체 학습의 큰 흐름","depth":2},{"id":"reading-2","label":"I run.","depth":3},{"id":"reading-3","label":"Birds fly.","depth":3},{"id":"reading-4","label":"주어란?","depth":2},{"id":"reading-5","label":"동사란?","depth":2},{"id":"reading-6","label":"한국어와 가장 먼저 다른 점","depth":2},{"id":"reading-7","label":"오늘 배울 것은 딱 이것이다.","depth":3},{"id":"reading-8","label":"1단계 연습","depth":3}],"origin":"conversation","characters":2159,"aliases":{"structure":"concept","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"concept","topic-6":"concept","topic-7":"concept","topic-8":"concept","topic-9":"concept","topic-10":"concept","topic-11":"concept","topic-12":"concept"}},{"id":2,"title":"2단계 — be동사 am / is / are","html":"\u003ch1 id=\"lesson-title\" data-id=\"2\">2단계 — be동사 \u003ccode>am / is / are\u003c/code>\u003c/h1>\n\u003cp>1단계에서 배운 것:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>영어 문장 = 주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이번에는 영어에서 가장 기본적인 동사인 \u003cstrong>be동사\u003c/strong>를 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. be동사는 무슨 뜻인가?\u003c/h2>\n\u003cp>be동사는 주로\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>~이다 / ~에 있다 / ~한 상태이다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻을 만든다.\u003c/p>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">I am tired.\u003c/h3>\n\u003cp>나는 피곤하다.\u003c/p>\n\u003cul>\n\u003cli>\u003ccode>I\u003c/code> = 주어\u003c/li>\n\u003cli>\u003ccode>am\u003c/code> = be동사\u003c/li>\n\u003cli>\u003ccode>tired\u003c/code> = 피곤한 상태\u003c/li>\n\u003c/ul>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">She is a teacher.\u003c/h3>\n\u003cp>그녀는 선생님이다.\u003c/p>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">He is at home.\u003c/h3>\n\u003cp>그는 집에 있다.\u003c/p>\n\u003cp>즉, be동사는 \u003cstrong>행동\u003c/strong>보다는\u003cbr>\u003cstrong>정체, 상태, 위치\u003c/strong>를 연결해주는 동사라고 보면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">2. 주어에 따라 모양이 바뀐다\u003c/h2>\n\u003cp>현재형 be동사는 세 개다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>주어\u003c/th>\n\u003cth>be동사\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>I\u003c/td>\n\u003ctd>\u003cstrong>am\u003c/strong>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>you\u003c/td>\n\u003ctd>\u003cstrong>are\u003c/strong>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>he\u003c/td>\n\u003ctd>\u003cstrong>is\u003c/strong>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>she\u003c/td>\n\u003ctd>\u003cstrong>is\u003c/strong>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>it\u003c/td>\n\u003ctd>\u003cstrong>is\u003c/strong>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>we\u003c/td>\n\u003ctd>\u003cstrong>are\u003c/strong>\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>they\u003c/td>\n\u003ctd>\u003cstrong>are\u003c/strong>\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>가장 먼저 이렇게 묶어서 익히면 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I am\u003c/strong>\u003cbr>\u003cstrong>He / She / It is\u003c/strong>\u003cbr>\u003cstrong>You / We / They are\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">3. 문장 구조\u003c/h2>\n\u003cp>기본 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + be동사 + 설명\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>I\u003c/code>에 대해서 \u003ccode>tired\u003c/code>라고 설명한다.\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is\u003c/strong> happy.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>She\u003c/code>에 대해서 \u003ccode>happy\u003c/code>라고 설명한다.\u003c/p>\n\u003cblockquote>\n\u003cp>They \u003cstrong>are\u003c/strong> students.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>They\u003c/code>에 대해서 \u003ccode>students\u003c/code>라고 설명한다.\u003c/p>\n\u003cp>be동사가 \u003cstrong>주어와 뒤의 설명을 연결한다.\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. be동사 뒤에는 무엇이 오는가?\u003c/h2>\n\u003cp>지금은 세 가지만 알면 된다.\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">① 상태\u003c/h3>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>tired\u003c/strong>.\u003cbr>나는 피곤하다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>happy\u003c/strong>.\u003cbr>그녀는 행복하다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">② 정체\u003c/h3>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>a father\u003c/strong>.\u003cbr>나는 아빠다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>a teacher\u003c/strong>.\u003cbr>그녀는 선생님이다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">③ 위치\u003c/h3>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>at home\u003c/strong>.\u003cbr>나는 집에 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>at work\u003c/strong>.\u003cbr>그녀는 직장에 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be동사 = 주어가 무엇인지 / 어떤 상태인지 / 어디에 있는지를 연결\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">5. 한국어와 다른 점\u003c/h2>\n\u003cp>한국어에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 피곤해.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>피곤해\u003c/code> 자체가 문장을 끝낼 수 있다.\u003c/p>\n\u003cp>하지만 영어에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I tired.\u003cbr>✅ I \u003cstrong>am\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>영어에서 \u003ccode>tired\u003c/code>는 여기서 동사가 아니다.\u003c/p>\n\u003cp>그래서 문장을 만들어 줄 \u003cstrong>동사 \u003ccode>am\u003c/code>\u003c/strong>이 필요하다.\u003c/p>\n\u003cp>마찬가지:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She happy.\u003cbr>✅ She \u003cstrong>is\u003c/strong> happy.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ They busy.\u003cbr>✅ They \u003cstrong>are\u003c/strong> busy.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">핵심\u003c/h2>\n\u003cp>오늘은 이것만 기억하면 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I am\u003c/strong>\u003cbr>\u003cstrong>He / She / It is\u003c/strong>\u003cbr>\u003cstrong>You / We / They are\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + be동사 + 설명\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">연습\u003c/h2>\n\u003cp>빈칸에 \u003ccode>am / is / are\u003c/code>를 넣어봐.\u003c/p>\n\u003col>\n\u003cli>I ___ tired.  \u003c/li>\n\u003cli>She ___ happy.  \u003c/li>\n\u003cli>They ___ busy.  \u003c/li>\n\u003cli>He ___ at home.  \u003c/li>\n\u003cli>We ___ ready.  \u003c/li>\n\u003cli>You ___ kind.\u003c/li>\n\u003c/ol>\n","toc":[{"id":"reading-1","label":"1. be동사는 무슨 뜻인가?","depth":2},{"id":"reading-2","label":"I am tired.","depth":3},{"id":"reading-3","label":"She is a teacher.","depth":3},{"id":"reading-4","label":"He is at home.","depth":3},{"id":"reading-5","label":"2. 주어에 따라 모양이 바뀐다","depth":2},{"id":"reading-6","label":"3. 문장 구조","depth":2},{"id":"reading-7","label":"4. be동사 뒤에는 무엇이 오는가?","depth":2},{"id":"reading-8","label":"① 상태","depth":3},{"id":"reading-9","label":"② 정체","depth":3},{"id":"reading-10","label":"③ 위치","depth":3},{"id":"reading-11","label":"5. 한국어와 다른 점","depth":2},{"id":"reading-12","label":"핵심","depth":2},{"id":"reading-13","label":"연습","depth":2}],"origin":"conversation","characters":1772,"aliases":{"structure":"reading-5","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-5","topic-3":"reading-6","topic-4":"reading-7","topic-5":"reading-11","topic-6":"reading-12","topic-7":"reading-13","topic-8":"concept","topic-9":"concept","topic-10":"concept","topic-11":"concept","topic-12":"concept"}},{"id":3,"title":"3단계 — 일반동사","html":"\u003ch1 id=\"lesson-title\" data-id=\"3\">3단계 — 일반동사\u003c/h1>\n\u003cp>앞에서 배운 것:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이번에는 \u003ccode>be동사\u003c/code>가 아닌 \u003cstrong>일반동사\u003c/strong>를 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 일반동사란?\u003c/h2>\n\u003cp>행동이나 동작, 상태를 나타내는 동사다.\u003c/p>\n\u003cul>\n\u003cli>eat = 먹다\u003c/li>\n\u003cli>go = 가다\u003c/li>\n\u003cli>like = 좋아하다\u003c/li>\n\u003cli>work = 일하다\u003c/li>\n\u003cli>sleep = 자다\u003c/li>\n\u003cli>play = 놀다\u003c/li>\n\u003c/ul>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I work.\u003cbr>나는 일한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They sleep.\u003cbr>그들은 잔다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We play.\u003cbr>우리는 논다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. be동사와 일반동사의 차이\u003c/h2>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">be동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>tired\u003c/code>는 상태다.\u003c/p>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">일반동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>work\u003c/code> 자체가 동사다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I am work.\u003cbr>✅ I work.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ She is eat.\u003cbr>✅ She eats.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>work\u003c/code>, \u003ccode>eat\u003c/code>, \u003ccode>sleep\u003c/code> 같은 단어가 이미 동사이기 때문에\u003cbr>앞에 \u003ccode>am / is / are\u003c/code>를 붙이지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 가장 중요한 규칙\u003c/h2>\n\u003cp>현재형에서 주어가\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>he / she / it\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이면 일반동사 뒤에 보통 \u003cstrong>-s\u003c/strong>를 붙인다.\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">I / You / We / They\u003c/h3>\n\u003cblockquote>\n\u003cp>I work.\u003cbr>You work.\u003cbr>We work.\u003cbr>They work.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">He / She / It\u003c/h3>\n\u003cblockquote>\n\u003cp>He work\u003cstrong>s\u003c/strong>.\u003cbr>She work\u003cstrong>s\u003c/strong>.\u003cbr>It work\u003cstrong>s\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">4. 예문\u003c/h2>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">eat\u003c/h3>\n\u003cblockquote>\n\u003cp>I eat.\u003cbr>She eats.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">like\u003c/h3>\n\u003cblockquote>\n\u003cp>I like coffee.\u003cbr>He likes coffee.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">sleep\u003c/h3>\n\u003cblockquote>\n\u003cp>They sleep.\u003cbr>My daughter sleeps.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">5. 왜 \u003ccode>s\u003c/code>가 붙는가?\u003c/h2>\n\u003cp>영어에서는 현재형 문장에서\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어가 3인칭 단수인지 표시\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>하기 위해 동사 모양을 바꾼다.\u003c/p>\n\u003cp>지금은 용어보다 이렇게 기억하면 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>I / you / we / they → 동사 그대로\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>he / she / it → 동사 + s\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>사람 이름 하나도 \u003ccode>he / she\u003c/code>와 같다.\u003c/p>\n\u003cblockquote>\n\u003cp>Narin sleeps.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>Narin\u003c/code> = 한 사람 = \u003ccode>she\u003c/code>\u003c/p>\n\u003cp>그래서 \u003ccode>sleep → sleeps\u003c/code>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">6. be동사와 비교\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>주어\u003c/th>\n\u003cth>be동사\u003c/th>\n\u003cth>일반동사\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>I\u003c/td>\n\u003ctd>am\u003c/td>\n\u003ctd>work\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>you\u003c/td>\n\u003ctd>are\u003c/td>\n\u003ctd>work\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>he\u003c/td>\n\u003ctd>is\u003c/td>\n\u003ctd>works\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>she\u003c/td>\n\u003ctd>is\u003c/td>\n\u003ctd>works\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>it\u003c/td>\n\u003ctd>is\u003c/td>\n\u003ctd>works\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>we\u003c/td>\n\u003ctd>are\u003c/td>\n\u003ctd>work\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>they\u003c/td>\n\u003ctd>are\u003c/td>\n\u003ctd>work\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>이 차이는 반드시 구분해야 한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am\u003c/strong> tired.\u003cbr>I \u003cstrong>work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is\u003c/strong> tired.\u003cbr>She \u003cstrong>works\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">핵심\u003c/h2>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">be동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am\u003c/strong>\u003cbr>He / She / It \u003cstrong>is\u003c/strong>\u003cbr>You / We / They \u003cstrong>are\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">일반동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I / You / We / They \u003cstrong>work\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He / She / It \u003cstrong>works\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I \u003cstrong>work / works\u003c/strong> every day.\u003c/li>\n\u003cli>She \u003cstrong>like / likes\u003c/strong> coffee.\u003c/li>\n\u003cli>They \u003cstrong>sleep / sleeps\u003c/strong> early.\u003c/li>\n\u003cli>He \u003cstrong>eat / eats\u003c/strong> breakfast.\u003c/li>\n\u003cli>Narin \u003cstrong>play / plays\u003c/strong> outside.\u003c/li>\n\u003c/ol>\n","toc":[{"id":"reading-1","label":"1. 일반동사란?","depth":2},{"id":"reading-2","label":"2. be동사와 일반동사의 차이","depth":2},{"id":"reading-3","label":"be동사","depth":3},{"id":"reading-4","label":"일반동사","depth":3},{"id":"reading-5","label":"3. 가장 중요한 규칙","depth":2},{"id":"reading-6","label":"I / You / We / They","depth":3},{"id":"reading-7","label":"He / She / It","depth":3},{"id":"reading-8","label":"4. 예문","depth":2},{"id":"reading-9","label":"eat","depth":3},{"id":"reading-10","label":"like","depth":3},{"id":"reading-11","label":"sleep","depth":3},{"id":"reading-12","label":"5. 왜 s가 붙는가?","depth":2},{"id":"reading-13","label":"6. be동사와 비교","depth":2},{"id":"reading-14","label":"핵심","depth":2},{"id":"reading-15","label":"be동사","depth":3},{"id":"reading-16","label":"일반동사","depth":3},{"id":"reading-17","label":"연습","depth":2}],"origin":"conversation","characters":1798,"aliases":{"structure":"concept","examples":"reading-8","contrast":"reading-2","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-5","topic-4":"reading-8","topic-5":"reading-12","topic-6":"reading-13","topic-7":"reading-14","topic-8":"reading-17","topic-9":"concept","topic-10":"concept","topic-11":"concept","topic-12":"concept"}},{"id":4,"title":"4단계 — 인칭대명사","html":"\u003ch1 id=\"lesson-title\" data-id=\"4\">4단계 — 인칭대명사\u003c/h1>\n\u003cp>지금까지 문장을 만들 때 계속 나온:\u003c/p>\n\u003cblockquote>\n\u003cp>I / you / he / she / it / we / they\u003c/p>\n\u003c/blockquote>\n\u003cp>이게 \u003cstrong>인칭대명사\u003c/strong>다.\u003c/p>\n\u003cp>쉽게 말하면 \u003cstrong>사람이나 사물의 이름을 대신하는 말\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 왜 필요한가?\u003c/h2>\n\u003cp>같은 이름을 계속 반복하면 어색하다.\u003c/p>\n\u003cblockquote>\n\u003cp>Narin is six years old.\u003cbr>Narin is happy.\u003cbr>Narin likes swimming.\u003c/p>\n\u003c/blockquote>\n\u003cp>영어에서는 보통 두 번째부터 이름 대신 대명사를 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>Narin is six years old.\u003cbr>\u003cstrong>She\u003c/strong> is happy.\u003cbr>\u003cstrong>She\u003c/strong> likes swimming.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 기본 인칭대명사\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>영어\u003c/th>\n\u003cth>뜻\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>I\u003c/td>\n\u003ctd>나\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>you\u003c/td>\n\u003ctd>너 / 당신 / 너희\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>he\u003c/td>\n\u003ctd>그 남자\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>she\u003c/td>\n\u003ctd>그 여자\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>it\u003c/td>\n\u003ctd>그것\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>we\u003c/td>\n\u003ctd>우리\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>they\u003c/td>\n\u003ctd>그들 / 그것들\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>he / she / it\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">he\u003c/h3>\n\u003cp>남자 한 명\u003c/p>\n\u003cblockquote>\n\u003cp>Tom is my friend.\u003cbr>\u003cstrong>He\u003c/strong> is kind.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">she\u003c/h3>\n\u003cp>여자 한 명\u003c/p>\n\u003cblockquote>\n\u003cp>Mina is my friend.\u003cbr>\u003cstrong>She\u003c/strong> is kind.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">it\u003c/h3>\n\u003cp>사람이 아닌 사물이나 동물 하나\u003c/p>\n\u003cblockquote>\n\u003cp>The car is new.\u003cbr>\u003cstrong>It\u003c/strong> is expensive.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>The dog is cute.\u003cbr>\u003cstrong>It\u003c/strong> is small.\u003c/p>\n\u003c/blockquote>\n\u003cp>다만 반려동물처럼 성별을 알고 중요하게 생각하면 \u003ccode>he / she\u003c/code>도 자주 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. \u003ccode>we\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>we\u003c/code>는 \u003cstrong>나를 포함한 여러 명\u003c/strong>이다.\u003c/p>\n\u003cblockquote>\n\u003cp>My wife and I\u003cbr>→ \u003cstrong>we\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Narin and I\u003cbr>→ \u003cstrong>we\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>My wife and I are tired.\u003cbr>\u003cstrong>We\u003c/strong> are tired.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. \u003ccode>they\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>they\u003c/code>는 \u003cstrong>나를 포함하지 않는 여러 명\u003c/strong>이다.\u003c/p>\n\u003cblockquote>\n\u003cp>Tom and Jane\u003cbr>→ \u003cstrong>they\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>My parents\u003cbr>→ \u003cstrong>they\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>The dogs\u003cbr>→ \u003cstrong>they\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>사람뿐 아니라 사물 여러 개에도 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>The books are new.\u003cbr>\u003cstrong>They\u003c/strong> are new.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. \u003ccode>you\u003c/code>의 특징\u003c/h2>\n\u003cp>\u003ccode>you\u003c/code>는 조금 특이하다.\u003c/p>\n\u003cp>한 명에게도:\u003c/p>\n\u003cblockquote>\n\u003cp>You are nice.\u003cbr>너는 친절하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여러 명에게도:\u003c/p>\n\u003cblockquote>\n\u003cp>You are nice.\u003cbr>너희는 친절하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 \u003ccode>you\u003c/code>다.\u003c/p>\n\u003cp>영어에서는 문맥으로 구분한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">7. 지금까지 배운 문법과 연결\u003c/h2>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">be동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am\u003c/strong> tired.\u003cbr>He \u003cstrong>is\u003c/strong> tired.\u003cbr>She \u003cstrong>is\u003c/strong> tired.\u003cbr>It \u003cstrong>is\u003c/strong> tired.\u003cbr>We \u003cstrong>are\u003c/strong> tired.\u003cbr>You \u003cstrong>are\u003c/strong> tired.\u003cbr>They \u003cstrong>are\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">일반동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>work\u003c/strong>.\u003cbr>You \u003cstrong>work\u003c/strong>.\u003cbr>We \u003cstrong>work\u003c/strong>.\u003cbr>They \u003cstrong>work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>He \u003cstrong>works\u003c/strong>.\u003cbr>She \u003cstrong>works\u003c/strong>.\u003cbr>It \u003cstrong>works\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 중요한 묶음이 다시 나온다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>he / she / it = 한 그룹\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 그룹은 be동사에서는 \u003ccode>is\u003c/code>, 일반동사 현재형에서는 \u003ccode>-s\u003c/code>가 붙는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">핵심\u003c/h2>\n\u003cp>이름을 대명사로 바꿀 때:\u003c/p>\n\u003cblockquote>\n\u003cp>John → \u003cstrong>he\u003c/strong>\u003cbr>Sarah → \u003cstrong>she\u003c/strong>\u003cbr>a car → \u003cstrong>it\u003c/strong>\u003cbr>John and Sarah → \u003cstrong>they\u003c/strong>\u003cbr>my wife and I → \u003cstrong>we\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">연습\u003c/h2>\n\u003cp>다음을 대명사로 바꿔봐.\u003c/p>\n\u003col>\n\u003cli>Tom → ?\u003c/li>\n\u003cli>Mina → ?\u003c/li>\n\u003cli>The cat → ?\u003c/li>\n\u003cli>Tom and Mina → ?\u003c/li>\n\u003cli>My daughter and I → ?\u003c/li>\n\u003cli>My parents → ?\u003c/li>\n\u003c/ol>\n","toc":[{"id":"reading-1","label":"1. 왜 필요한가?","depth":2},{"id":"reading-2","label":"2. 기본 인칭대명사","depth":2},{"id":"reading-3","label":"3. he / she / it","depth":2},{"id":"reading-4","label":"he","depth":3},{"id":"reading-5","label":"she","depth":3},{"id":"reading-6","label":"it","depth":3},{"id":"reading-7","label":"4. we","depth":2},{"id":"reading-8","label":"5. they","depth":2},{"id":"reading-9","label":"6. you의 특징","depth":2},{"id":"reading-10","label":"7. 지금까지 배운 문법과 연결","depth":2},{"id":"reading-11","label":"be동사","depth":3},{"id":"reading-12","label":"일반동사","depth":3},{"id":"reading-13","label":"핵심","depth":2},{"id":"reading-14","label":"연습","depth":2}],"origin":"conversation","characters":1993,"aliases":{"structure":"concept","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-7","topic-5":"reading-8","topic-6":"reading-9","topic-7":"reading-10","topic-8":"reading-13","topic-9":"reading-14","topic-10":"concept","topic-11":"concept","topic-12":"concept"}},{"id":5,"title":"5단계 — 부정문","html":"\u003ch1 id=\"lesson-title\" data-id=\"5\">5단계 — 부정문\u003c/h1>\n\u003cp>이번에는 \u003cstrong>“~이 아니다 / ~하지 않는다”\u003c/strong>를 만든다.\u003c/p>\n\u003cp>영어의 부정문은 먼저 \u003cstrong>be동사 문장인지, 일반동사 문장인지\u003c/strong> 구분해야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. be동사 부정문\u003c/h2>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + be동사 + not\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">긍정\u003c/h3>\n\u003cblockquote>\n\u003cp>I am tired.\u003cbr>나는 피곤하다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">부정\u003c/h3>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>not\u003c/strong> tired.\u003cbr>나는 피곤하지 않다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">예문\u003c/h3>\n\u003cblockquote>\n\u003cp>She is happy.\u003cbr>→ She is \u003cstrong>not\u003c/strong> happy.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He is at home.\u003cbr>→ He is \u003cstrong>not\u003c/strong> at home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They are busy.\u003cbr>→ They are \u003cstrong>not\u003c/strong> busy.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉, be동사는 아주 간단하다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be동사 바로 뒤에 not\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">2. 일반동사 부정문\u003c/h2>\n\u003cp>일반동사는 동사 뒤에 바로 \u003ccode>not\u003c/code>을 붙이지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I work not.\u003cbr>❌ She likes not coffee.\u003c/p>\n\u003c/blockquote>\n\u003cp>영어에서는 \u003cstrong>do\u003c/strong>라는 동사를 이용한다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + do not + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I work.\u003cbr>→ I \u003cstrong>do not work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They like coffee.\u003cbr>→ They \u003cstrong>do not like\u003c/strong> coffee.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">3. he / she / it은 \u003ccode>does\u003c/code>\u003c/h2>\n\u003cp>앞에서 배웠다.\u003c/p>\n\u003cp>긍정문:\u003c/p>\n\u003cblockquote>\n\u003cp>She work\u003cstrong>s\u003c/strong>.\u003cbr>He like\u003cstrong>s\u003c/strong> coffee.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 부정문에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>She \u003cstrong>does not work\u003c/strong>.\u003cbr>He \u003cstrong>does not like\u003c/strong> coffee.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 중요한 규칙이 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>does가 나오면 뒤의 일반동사는 원래 모양으로 돌아간다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She does not works.\u003cbr>✅ She does not work.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ He does not likes coffee.\u003cbr>✅ He does not like coffee.\u003c/p>\n\u003c/blockquote>\n\u003cp>왜냐하면 \u003ccode>does\u003c/code>가 이미 \u003cstrong>he / she / it의 표시\u003c/strong>를 담당하고 있기 때문이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. 전체 구조 비교\u003c/h2>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">I / you / we / they\u003c/h3>\n\u003cblockquote>\n\u003cp>I work.\u003cbr>I \u003cstrong>do not work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They like coffee.\u003cbr>They \u003cstrong>do not like\u003c/strong> coffee.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">he / she / it\u003c/h3>\n\u003cblockquote>\n\u003cp>She works.\u003cbr>She \u003cstrong>does not work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He likes coffee.\u003cbr>He \u003cstrong>does not like\u003c/strong> coffee.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">5. 축약형\u003c/h2>\n\u003cp>회화에서는 보통 이렇게 쓴다.\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">do not\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>don&#39;t\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">does not\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>doesn&#39;t\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I don&#39;t know.\u003cbr>나는 몰라.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They don&#39;t work here.\u003cbr>그들은 여기서 일하지 않아.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She doesn&#39;t like coffee.\u003cbr>그녀는 커피를 좋아하지 않아.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He doesn&#39;t eat breakfast.\u003cbr>그는 아침을 먹지 않아.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">6. be동사와 일반동사를 반드시 구분\u003c/h2>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">be동사\u003c/h2>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is not\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>do\u003c/code>를 쓰지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She doesn&#39;t be tired.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">일반동사\u003c/h2>\n\u003cblockquote>\n\u003cp>She \u003cstrong>doesn&#39;t work\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>is not\u003c/code>을 쓰지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She isn&#39;t work.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">핵심 공식\u003c/h2>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">be동사\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + am/is/are + not\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">일반동사\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>I / you / we / they + don&#39;t + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>he / she / it + doesn&#39;t + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">연습\u003c/h2>\n\u003cp>긍정문을 부정문으로 바꿔봐.\u003c/p>\n\u003col>\n\u003cli>I am tired.  \u003c/li>\n\u003cli>She is busy.  \u003c/li>\n\u003cli>I like coffee.  \u003c/li>\n\u003cli>They work here.  \u003c/li>\n\u003cli>He likes pizza.  \u003c/li>\n\u003cli>Narin plays outside.\u003c/li>\n\u003c/ol>\n","toc":[{"id":"reading-1","label":"1. be동사 부정문","depth":2},{"id":"reading-2","label":"긍정","depth":3},{"id":"reading-3","label":"부정","depth":3},{"id":"reading-4","label":"예문","depth":3},{"id":"reading-5","label":"2. 일반동사 부정문","depth":2},{"id":"reading-6","label":"3. he / she / it은 does","depth":2},{"id":"reading-7","label":"4. 전체 구조 비교","depth":2},{"id":"reading-8","label":"I / you / we / they","depth":3},{"id":"reading-9","label":"he / she / it","depth":3},{"id":"reading-10","label":"5. 축약형","depth":2},{"id":"reading-11","label":"do not","depth":3},{"id":"reading-12","label":"does not","depth":3},{"id":"reading-13","label":"6. be동사와 일반동사를 반드시 구분","depth":2},{"id":"reading-14","label":"be동사","depth":2},{"id":"reading-15","label":"일반동사","depth":2},{"id":"reading-16","label":"핵심 공식","depth":2},{"id":"reading-17","label":"be동사","depth":3},{"id":"reading-18","label":"일반동사","depth":3},{"id":"reading-19","label":"연습","depth":2}],"origin":"conversation","characters":2042,"aliases":{"structure":"reading-7","examples":"reading-4","contrast":"reading-7","topic-1":"reading-1","topic-2":"reading-5","topic-3":"reading-6","topic-4":"reading-7","topic-5":"reading-10","topic-6":"reading-13","topic-7":"reading-14","topic-8":"reading-15","topic-9":"reading-16","topic-10":"reading-19","topic-11":"concept","topic-12":"concept"}},{"id":6,"title":"6단계 — 의문문","html":"\u003ch1 id=\"lesson-title\" data-id=\"6\">6단계 — 의문문\u003c/h1>\n\u003cp>이번에는 \u003cstrong>“~이야?” / “~해?”\u003c/strong>처럼 질문하는 문장을 만든다.\u003c/p>\n\u003cp>부정문과 마찬가지로 먼저 구분한다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>① be동사 문장인지\u003c/strong>\u003cbr>\u003cstrong>② 일반동사 문장인지\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. be동사 의문문\u003c/h2>\n\u003cp>평서문:\u003c/p>\n\u003cblockquote>\n\u003cp>You are tired.\u003cbr>너는 피곤하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>의문문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Are you tired?\u003c/strong>\u003cbr>너 피곤해?\u003c/p>\n\u003c/blockquote>\n\u003cp>핵심은 간단하다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be동사를 주어 앞으로 보낸다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">구조\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>be동사 + 주어 + 나머지?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">예문\u003c/h3>\n\u003cblockquote>\n\u003cp>She is busy.\u003cbr>→ \u003cstrong>Is she busy?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He is at home.\u003cbr>→ \u003cstrong>Is he at home?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They are ready.\u003cbr>→ \u003cstrong>Are they ready?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>You are happy.\u003cbr>→ \u003cstrong>Are you happy?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. \u003ccode>I am\u003c/code>은 어떻게 질문할까?\u003c/h2>\n\u003cp>평서문:\u003c/p>\n\u003cblockquote>\n\u003cp>I am late.\u003cbr>나는 늦었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Am I late?\u003c/strong>\u003cbr>나 늦었어?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>am\u003c/code>도 똑같이 앞으로 간다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 일반동사 의문문\u003c/h2>\n\u003cp>평서문:\u003c/p>\n\u003cblockquote>\n\u003cp>You like coffee.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문할 때 일반동사를 앞으로 보내지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Like you coffee?\u003c/p>\n\u003c/blockquote>\n\u003cp>대신 \u003ccode>do\u003c/code>를 앞에 둔다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Do you like coffee?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">구조\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Do + 주어 + 동사원형?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. he / she / it은 \u003ccode>does\u003c/code>\u003c/h2>\n\u003cp>평서문:\u003c/p>\n\u003cblockquote>\n\u003cp>She likes coffee.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Does she like coffee?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 다시 중요한 규칙:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>does\u003c/code>가 나오면 뒤의 동사는 \u003cstrong>원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Does she likes coffee?\u003cbr>✅ Does she like coffee?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">비교\u003c/h3>\n\u003cblockquote>\n\u003cp>He works here.\u003cbr>→ \u003cstrong>Does he work here?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She plays tennis.\u003cbr>→ \u003cstrong>Does she play tennis?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Narin likes swimming.\u003cbr>→ \u003cstrong>Does Narin like swimming?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. I / you / we / they\u003c/h2>\n\u003cp>이쪽은 \u003ccode>do\u003c/code>를 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>You work here.\u003cbr>→ \u003cstrong>Do you work here?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They like pizza.\u003cbr>→ \u003cstrong>Do they like pizza?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We need this.\u003cbr>→ \u003cstrong>Do we need this?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. be동사와 일반동사의 차이\u003c/h2>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">be동사\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Is\u003c/strong> she tired?\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>is\u003c/code>가 직접 앞으로 간다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">일반동사\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>likes\u003c/strong> coffee.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Does\u003c/strong> she \u003cstrong>like\u003c/strong> coffee?\u003c/p>\n\u003c/blockquote>\n\u003cp>일반동사는 앞으로 가지 않고 \u003ccode>do / does\u003c/code>를 사용한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. 지금까지 구조 비교\u003c/h2>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">be동사\u003c/h2>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">평서문\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is\u003c/strong> busy.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">부정문\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is not\u003c/strong> busy.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">의문문\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Is\u003c/strong> she busy?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">일반동사\u003c/h2>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">평서문\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>works\u003c/strong> here.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">부정문\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>doesn&#39;t work\u003c/strong> here.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">의문문\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Does\u003c/strong> she \u003cstrong>work\u003c/strong> here?\u003c/p>\n\u003c/blockquote>\n\u003cp>이 세 형태를 하나의 묶음으로 익히면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">핵심 공식\u003c/h2>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">be동사 질문\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Am / Is / Are + 주어 + 나머지?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-24\" data-reading-anchor=\"reading-24\">일반동사 질문\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Do + I/you/we/they + 동사원형?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>Does + he/she/it + 동사원형?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-25\" data-reading-anchor=\"reading-25\">연습\u003c/h2>\n\u003cp>다음을 의문문으로 바꿔봐.\u003c/p>\n\u003col>\n\u003cli>You are tired.  \u003c/li>\n\u003cli>She is busy.  \u003c/li>\n\u003cli>They are at home.  \u003c/li>\n\u003cli>You like coffee.  \u003c/li>\n\u003cli>He works here.  \u003c/li>\n\u003cli>Narin likes pizza.\u003c/li>\n\u003c/ol>\n","toc":[{"id":"reading-1","label":"1. be동사 의문문","depth":2},{"id":"reading-2","label":"구조","depth":3},{"id":"reading-3","label":"예문","depth":3},{"id":"reading-4","label":"2. I am은 어떻게 질문할까?","depth":2},{"id":"reading-5","label":"3. 일반동사 의문문","depth":2},{"id":"reading-6","label":"구조","depth":3},{"id":"reading-7","label":"4. he / she / it은 does","depth":2},{"id":"reading-8","label":"비교","depth":3},{"id":"reading-9","label":"5. I / you / we / they","depth":2},{"id":"reading-10","label":"6. be동사와 일반동사의 차이","depth":2},{"id":"reading-11","label":"be동사","depth":3},{"id":"reading-12","label":"일반동사","depth":3},{"id":"reading-13","label":"7. 지금까지 구조 비교","depth":2},{"id":"reading-14","label":"be동사","depth":2},{"id":"reading-15","label":"평서문","depth":3},{"id":"reading-16","label":"부정문","depth":3},{"id":"reading-17","label":"의문문","depth":3},{"id":"reading-18","label":"일반동사","depth":2},{"id":"reading-19","label":"평서문","depth":3},{"id":"reading-20","label":"부정문","depth":3},{"id":"reading-21","label":"의문문","depth":3},{"id":"reading-22","label":"핵심 공식","depth":2},{"id":"reading-23","label":"be동사 질문","depth":3},{"id":"reading-24","label":"일반동사 질문","depth":3},{"id":"reading-25","label":"연습","depth":2}],"origin":"conversation","characters":2081,"aliases":{"structure":"reading-2","examples":"reading-3","contrast":"reading-8","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-7","topic-5":"reading-9","topic-6":"reading-10","topic-7":"reading-13","topic-8":"reading-14","topic-9":"reading-18","topic-10":"reading-22","topic-11":"reading-25","topic-12":"concept"}},{"id":7,"title":"7단계 — 목적어(Object)","html":"\u003ch1 id=\"lesson-title\" data-id=\"7\">7단계 — 목적어(Object)\u003c/h1>\n\u003cp>여기서부터는 \u003cstrong>관사보다 먼저 문장 구조를 완성하는 게 맞다.\u003c/strong>\u003cbr>지금까지 \u003ccode>주어 + 동사\u003c/code>를 배웠으니, 다음은 \u003cstrong>목적어\u003c/strong>다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 목적어란?\u003c/h2>\n\u003cp>동사의 행동을 \u003cstrong>받는 대상\u003c/strong>이다.\u003c/p>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>coffee\u003c/strong>.\u003cbr>나는 \u003cstrong>커피를\u003c/strong> 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>\u003ccode>I\u003c/code> = 주어\u003c/li>\n\u003cli>\u003ccode>like\u003c/code> = 동사\u003c/li>\n\u003cli>\u003ccode>coffee\u003c/code> = 목적어\u003c/li>\n\u003c/ul>\n\u003cp>한국어의 \u003cstrong>“~을 / ~를”\u003c/strong>에 해당하는 경우가 많다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사 + 목적어\u003c/strong>\u003cbr>\u003cstrong>S + V + O\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">I eat pizza.\u003c/h3>\n\u003cp>나는 피자를 먹는다.\u003c/p>\n\u003cul>\n\u003cli>I → 누가? → \u003cstrong>주어\u003c/strong>\u003c/li>\n\u003cli>eat → 무엇을 하다? → \u003cstrong>동사\u003c/strong>\u003c/li>\n\u003cli>pizza → 무엇을 먹다? → \u003cstrong>목적어\u003c/strong>\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">She likes music.\u003c/h3>\n\u003cblockquote>\n\u003cp>She / likes / music\u003cbr>주어 / 동사 / 목적어\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">Narin reads books.\u003c/h3>\n\u003cblockquote>\n\u003cp>Narin / reads / books\u003cbr>주어 / 동사 / 목적어\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">3. 모든 동사에 목적어가 필요한 것은 아니다\u003c/h2>\n\u003cp>이게 중요하다.\u003c/p>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">목적어 없이 가능한 동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I sleep.\u003cbr>나는 잔다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>sleep\u003c/code> 뒤에 반드시 대상이 필요하지 않다.\u003c/p>\n\u003cblockquote>\n\u003cp>The baby cries.\u003cbr>아기가 운다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">목적어가 필요한 동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>coffee\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>I like.\u003c/code>만 말하면 보통\u003c/p>\n\u003cblockquote>\n\u003cp>뭘 좋아하는데?\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 느낌이 든다.\u003c/p>\n\u003cblockquote>\n\u003cp>I need \u003cstrong>water\u003c/strong>.\u003cbr>I want \u003cstrong>coffee\u003c/strong>.\u003cbr>I have \u003cstrong>a car\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>이런 동사들은 뒤에 대상이 자연스럽게 따라온다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">4. 한국어와 영어의 어순 차이\u003c/h2>\n\u003cp>한국어:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 커피를 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>순서:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 / 커피를 / 좋아한다\u003cbr>\u003cstrong>주어 + 목적어 + 동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>영어:\u003c/p>\n\u003cblockquote>\n\u003cp>I / like / coffee.\u003cbr>\u003cstrong>주어 + 동사 + 목적어\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>즉,\u003c/p>\n\u003cblockquote>\n\u003cp>한국어: \u003cstrong>S + O + V\u003c/strong>\u003cbr>영어: \u003cstrong>S + V + O\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 차이가 영어 문장을 만드는 데 매우 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">5. 지금까지 배운 문장 구조\u003c/h2>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">주어 + 동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I sleep.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">주어 + be동사 + 설명\u003c/h3>\n\u003cblockquote>\n\u003cp>I am tired.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">주어 + 일반동사 + 목적어\u003c/h3>\n\u003cblockquote>\n\u003cp>I like coffee.\u003c/p>\n\u003c/blockquote>\n\u003cp>이제 영어의 가장 기본적인 세 문장 형태가 보이기 시작한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">핵심\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어(S)\u003c/strong> = 누가 / 무엇이\u003cbr>\u003cstrong>동사(V)\u003c/strong> = 무엇을 한다\u003cbr>\u003cstrong>목적어(O)\u003c/strong> = 그 행동의 대상\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>She likes pizza.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>She = S\u003c/li>\n\u003cli>likes = V\u003c/li>\n\u003cli>pizza = O\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">연습\u003c/h2>\n\u003cp>각 문장의 \u003ccode>S / V / O\u003c/code>를 찾아봐.\u003c/p>\n\u003col>\n\u003cli>I like coffee.\u003c/li>\n\u003cli>She eats pizza.\u003c/li>\n\u003cli>They watch TV.\u003c/li>\n\u003cli>Narin reads books.\u003c/li>\n\u003cli>We need water.\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계에서는 \u003cstrong>명사가 무엇인지\u003c/strong>부터 들어간다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 목적어란?","depth":2},{"id":"reading-2","label":"2. 기본 구조","depth":2},{"id":"reading-3","label":"I eat pizza.","depth":3},{"id":"reading-4","label":"She likes music.","depth":3},{"id":"reading-5","label":"Narin reads books.","depth":3},{"id":"reading-6","label":"3. 모든 동사에 목적어가 필요한 것은 아니다","depth":2},{"id":"reading-7","label":"목적어 없이 가능한 동사","depth":3},{"id":"reading-8","label":"목적어가 필요한 동사","depth":3},{"id":"reading-9","label":"4. 한국어와 영어의 어순 차이","depth":2},{"id":"reading-10","label":"5. 지금까지 배운 문장 구조","depth":2},{"id":"reading-11","label":"주어 + 동사","depth":3},{"id":"reading-12","label":"주어 + be동사 + 설명","depth":3},{"id":"reading-13","label":"주어 + 일반동사 + 목적어","depth":3},{"id":"reading-14","label":"핵심","depth":2},{"id":"reading-15","label":"연습","depth":2}],"origin":"conversation","characters":1574,"aliases":{"structure":"reading-2","examples":"concept","contrast":"reading-9","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-6","topic-4":"reading-9","topic-5":"reading-10","topic-6":"reading-14","topic-7":"reading-15","topic-8":"concept","topic-9":"concept","topic-10":"concept","topic-11":"concept","topic-12":"concept"}},{"id":8,"title":"8단계 — 명사(Noun)","html":"\u003ch1 id=\"lesson-title\" data-id=\"8\">8단계 — 명사(Noun)\u003c/h1>\n\u003cp>이번에는 \u003cstrong>명사 자체가 무엇인지\u003c/strong>부터 잡는다.\u003c/p>\n\u003cp>영어 문법에서 명사는 이후의 \u003ccode>a/an\u003c/code>, 복수형, 가산·불가산을 이해하기 위한 기반이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 명사란?\u003c/h2>\n\u003cp>명사는 \u003cstrong>사람, 사물, 장소, 동물, 개념의 이름\u003c/strong>이다.\u003c/p>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">사람\u003c/h3>\n\u003cul>\n\u003cli>teacher\u003c/li>\n\u003cli>doctor\u003c/li>\n\u003cli>child\u003c/li>\n\u003cli>friend\u003c/li>\n\u003c/ul>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">사물\u003c/h3>\n\u003cul>\n\u003cli>book\u003c/li>\n\u003cli>car\u003c/li>\n\u003cli>phone\u003c/li>\n\u003cli>table\u003c/li>\n\u003c/ul>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">장소\u003c/h3>\n\u003cul>\n\u003cli>school\u003c/li>\n\u003cli>home\u003c/li>\n\u003cli>office\u003c/li>\n\u003cli>park\u003c/li>\n\u003c/ul>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">동물\u003c/h3>\n\u003cul>\n\u003cli>dog\u003c/li>\n\u003cli>cat\u003c/li>\n\u003cli>bird\u003c/li>\n\u003c/ul>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">개념\u003c/h3>\n\u003cul>\n\u003cli>love\u003c/li>\n\u003cli>information\u003c/li>\n\u003cli>idea\u003c/li>\n\u003cli>time\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">2. 문장에서 명사가 들어가는 자리\u003c/h2>\n\u003cp>명사는 여러 자리에 들어갈 수 있다.\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">주어\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>Narin\u003c/strong> sleeps.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>Narin\u003c/code> = 명사\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>The dog\u003c/strong> runs.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>dog\u003c/code> = 명사\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">목적어\u003c/h3>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>coffee\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>coffee\u003c/code> = 명사\u003c/p>\n\u003cblockquote>\n\u003cp>She reads \u003cstrong>books\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>books\u003c/code> = 명사\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">be동사 뒤\u003c/h3>\n\u003cblockquote>\n\u003cp>She is a \u003cstrong>teacher\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>teacher\u003c/code> = 명사\u003c/p>\n\u003cp>즉 명사는 문장에서 주어도 되고, 목적어도 되고, 어떤 사람이나 사물이 무엇인지 설명할 수도 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">3. 명사와 동사를 구별하기\u003c/h2>\n\u003cp>같은 문장에서 역할을 보면 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>work\u003c/strong> at an \u003cstrong>office\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>\u003ccode>work\u003c/code> = 일하다 → 동사\u003c/li>\n\u003cli>\u003ccode>office\u003c/code> = 사무실 → 명사\u003c/li>\n\u003c/ul>\n\u003cblockquote>\n\u003cp>She \u003cstrong>drinks\u003c/strong> \u003cstrong>water\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>drinks = 동사\u003c/li>\n\u003cli>water = 명사\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">4. 명사와 형용사를 구별하기\u003c/h2>\n\u003cp>이것도 중요하다.\u003c/p>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">명사\u003c/h3>\n\u003cp>사람이나 사물 등의 \u003cstrong>이름\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>beauty\u003cbr>아름다움\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">형용사\u003c/h3>\n\u003cp>사람이나 사물이 \u003cstrong>어떤 상태인지\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>beautiful\u003cbr>아름다운\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>beautiful\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>beautiful\u003c/code>은 사람의 상태를 설명하므로 형용사다.\u003c/p>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>Beauty is important.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>beauty\u003c/code>는 &#39;아름다움&#39;이라는 개념의 이름이므로 명사다.\u003c/p>\n\u003cp>형용사는 나중에 별도로 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">5. 고유명사와 일반명사\u003c/h2>\n\u003cp>명사는 크게 두 가지로도 나눌 수 있다.\u003c/p>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">일반명사\u003c/h2>\n\u003cp>여러 대상에 공통으로 사용하는 이름.\u003c/p>\n\u003cul>\n\u003cli>girl\u003c/li>\n\u003cli>city\u003c/li>\n\u003cli>company\u003c/li>\n\u003cli>country\u003c/li>\n\u003cli>dog\u003c/li>\n\u003c/ul>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She is a \u003cstrong>girl\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">고유명사\u003c/h2>\n\u003cp>특정한 사람이나 장소 등의 이름.\u003c/p>\n\u003cul>\n\u003cli>Narin\u003c/li>\n\u003cli>Korea\u003c/li>\n\u003cli>Busan\u003c/li>\n\u003cli>Samsung\u003c/li>\n\u003c/ul>\n\u003cp>고유명사는 보통 \u003cstrong>첫 글자를 대문자로 쓴다.\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>I live in \u003cstrong>Busan\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">6. 앞으로 중요한 구분\u003c/h2>\n\u003cp>영어 명사를 배우면서 반드시 구분해야 하는 것이 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>하나인가 / 여러 개인가\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 이후에는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>셀 수 있는가 / 셀 수 없는가\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 구분한다.\u003c/p>\n\u003cp>하지만 아직 \u003ccode>a/an\u003c/code>이나 가산·불가산으로 바로 넘어가지 않는다.\u003c/p>\n\u003cp>먼저 \u003cstrong>단수와 복수\u003c/strong>부터 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">핵심\u003c/h2>\n\u003cp>명사 = \u003cstrong>이름을 나타내는 말\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>person / thing / place / animal / idea\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Tom\u003c/strong> likes \u003cstrong>coffee\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>Tom = 명사, 주어\u003c/li>\n\u003cli>likes = 동사\u003c/li>\n\u003cli>coffee = 명사, 목적어\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">연습\u003c/h2>\n\u003cp>다음 문장에서 \u003cstrong>명사만\u003c/strong> 찾아봐.\u003c/p>\n\u003col>\n\u003cli>Tom likes pizza.\u003c/li>\n\u003cli>Narin reads books.\u003c/li>\n\u003cli>The dog eats food.\u003c/li>\n\u003cli>Mina works in Busan.\u003c/li>\n\u003cli>Children like games.\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>9단계 — 명사의 단수와 복수\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 명사란?","depth":2},{"id":"reading-2","label":"사람","depth":3},{"id":"reading-3","label":"사물","depth":3},{"id":"reading-4","label":"장소","depth":3},{"id":"reading-5","label":"동물","depth":3},{"id":"reading-6","label":"개념","depth":3},{"id":"reading-7","label":"2. 문장에서 명사가 들어가는 자리","depth":2},{"id":"reading-8","label":"주어","depth":3},{"id":"reading-9","label":"목적어","depth":3},{"id":"reading-10","label":"be동사 뒤","depth":3},{"id":"reading-11","label":"3. 명사와 동사를 구별하기","depth":2},{"id":"reading-12","label":"4. 명사와 형용사를 구별하기","depth":2},{"id":"reading-13","label":"명사","depth":3},{"id":"reading-14","label":"형용사","depth":3},{"id":"reading-15","label":"5. 고유명사와 일반명사","depth":2},{"id":"reading-16","label":"일반명사","depth":2},{"id":"reading-17","label":"고유명사","depth":2},{"id":"reading-18","label":"6. 앞으로 중요한 구분","depth":2},{"id":"reading-19","label":"핵심","depth":2},{"id":"reading-20","label":"연습","depth":2}],"origin":"conversation","characters":1907,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-18","topic-1":"reading-1","topic-2":"reading-7","topic-3":"reading-11","topic-4":"reading-12","topic-5":"reading-15","topic-6":"reading-16","topic-7":"reading-17","topic-8":"reading-18","topic-9":"reading-19","topic-10":"reading-20","topic-11":"concept","topic-12":"concept"}},{"id":9,"title":"9단계 — 명사의 단수와 복수","html":"\u003ch1 id=\"lesson-title\" data-id=\"9\">9단계 — 명사의 단수와 복수\u003c/h1>\n\u003cp>이번에는 명사가 \u003cstrong>하나인지, 둘 이상인지\u003c/strong> 구분한다.\u003c/p>\n\u003cp>영어에서는 이 구분을 문장 안에서 아주 중요하게 본다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 단수와 복수\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">단수\u003c/h3>\n\u003cp>하나\u003c/p>\n\u003cblockquote>\n\u003cp>a book\u003cbr>책 한 권\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>a dog\u003cbr>개 한 마리\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">복수\u003c/h3>\n\u003cp>둘 이상\u003c/p>\n\u003cblockquote>\n\u003cp>two books\u003cbr>책 두 권\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>three dogs\u003cbr>개 세 마리\u003c/p>\n\u003c/blockquote>\n\u003cp>보통 복수형은 명사 뒤에 \u003cstrong>-s\u003c/strong>를 붙인다.\u003c/p>\n\u003cblockquote>\n\u003cp>book → books\u003cbr>dog → dogs\u003cbr>car → cars\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 기본 규칙\u003c/h2>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">대부분의 명사\u003c/h2>\n\u003cblockquote>\n\u003cp>명사 + \u003cstrong>s\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>cat → cats\u003c/li>\n\u003cli>apple → apples\u003c/li>\n\u003cli>table → tables\u003c/li>\n\u003cli>teacher → teachers\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">3. \u003ccode>-s\u003c/code>, \u003ccode>-x\u003c/code>, \u003ccode>-ch\u003c/code>, \u003ccode>-sh\u003c/code> 등으로 끝나는 경우\u003c/h2>\n\u003cp>보통 \u003cstrong>-es\u003c/strong>를 붙인다.\u003c/p>\n\u003cul>\n\u003cli>bus → buses\u003c/li>\n\u003cli>box → boxes\u003c/li>\n\u003cli>watch → watches\u003c/li>\n\u003cli>dish → dishes\u003c/li>\n\u003c/ul>\n\u003cp>이유는 발음을 자연스럽게 하기 위해서다.\u003c/p>\n\u003cblockquote>\n\u003cp>boxs ❌\u003cbr>boxes ✅\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. 자음 + y\u003c/h2>\n\u003cp>\u003ccode>y\u003c/code>를 \u003ccode>i\u003c/code>로 바꾸고 \u003ccode>-es\u003c/code>\u003c/p>\n\u003cul>\n\u003cli>baby → babies\u003c/li>\n\u003cli>city → cities\u003c/li>\n\u003cli>story → stories\u003c/li>\n\u003c/ul>\n\u003cp>하지만 앞에 모음이 있으면 그냥 \u003ccode>-s\u003c/code>\u003c/p>\n\u003cul>\n\u003cli>boy → boys\u003c/li>\n\u003cli>toy → toys\u003c/li>\n\u003cli>key → keys\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. 불규칙 복수형\u003c/h2>\n\u003cp>일부 명사는 \u003ccode>-s\u003c/code> 규칙을 따르지 않는다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>단수\u003c/th>\n\u003cth>복수\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>man\u003c/td>\n\u003ctd>men\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>woman\u003c/td>\n\u003ctd>women\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>child\u003c/td>\n\u003ctd>children\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>foot\u003c/td>\n\u003ctd>feet\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>tooth\u003c/td>\n\u003ctd>teeth\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>mouse\u003c/td>\n\u003ctd>mice\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>이건 규칙으로 만들기 어렵기 때문에 단어와 함께 익혀야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. 단수와 복수는 동사에도 영향을 준다\u003c/h2>\n\u003cp>이미 배운 내용과 연결된다.\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">단수\u003c/h3>\n\u003cblockquote>\n\u003cp>The dog \u003cstrong>runs\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>dog\u003c/code> 한 마리 → \u003ccode>it\u003c/code>과 같은 취급\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>runs\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">복수\u003c/h3>\n\u003cblockquote>\n\u003cp>The dogs \u003cstrong>run\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>dogs\u003c/code> 여러 마리 → \u003ccode>they\u003c/code>와 같은 취급\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>run\u003c/p>\n\u003c/blockquote>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>The child \u003cstrong>plays\u003c/strong>.\u003cbr>The children \u003cstrong>play\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">7. 대명사와 연결\u003c/h2>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">단수\u003c/h3>\n\u003cblockquote>\n\u003cp>The dog\u003cbr>→ \u003cstrong>it\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Tom\u003cbr>→ \u003cstrong>he\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Mina\u003cbr>→ \u003cstrong>she\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">복수\u003c/h3>\n\u003cblockquote>\n\u003cp>The dogs\u003cbr>→ \u003cstrong>they\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Tom and Mina\u003cbr>→ \u003cstrong>they\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">8. 숫자가 있으면 복수형\u003c/h2>\n\u003cblockquote>\n\u003cp>one book\u003cbr>two books\u003cbr>three books\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>one\u003c/code>일 때만 단수.\u003c/p>\n\u003cblockquote>\n\u003cp>one apple\u003cbr>five apples\u003c/p>\n\u003c/blockquote>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ two book\u003cbr>✅ two books\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">9. 아직 \u003ccode>a/an\u003c/code>은 완전히 배우지 않는다\u003c/h2>\n\u003cp>지금은 다음 정도만 알아두면 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>a book = 책 한 권\u003cbr>books = 책 여러 권\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 왜 \u003ccode>a\u003c/code>를 붙이는지, 언제 빼는지는 \u003cstrong>다음 단계에서 관사와 함께\u003c/strong> 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">핵심\u003c/h2>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">하나\u003c/h3>\n\u003cblockquote>\n\u003cp>book\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">둘 이상\u003c/h3>\n\u003cblockquote>\n\u003cp>books\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 현재형 일반동사에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>The dog \u003cstrong>runs\u003c/strong>.\u003cbr>The dogs \u003cstrong>run\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>명사의 단수·복수가 \u003cstrong>동사 형태에도 영향을 준다.\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">연습\u003c/h2>\n\u003cp>복수형으로 바꿔봐.\u003c/p>\n\u003col>\n\u003cli>dog → ?\u003c/li>\n\u003cli>box → ?\u003c/li>\n\u003cli>baby → ?\u003c/li>\n\u003cli>boy → ?\u003c/li>\n\u003cli>child → ?\u003c/li>\n\u003cli>woman → ?\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>10단계 — \u003ccode>a / an\u003c/code>과 관사\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 단수와 복수","depth":2},{"id":"reading-2","label":"단수","depth":3},{"id":"reading-3","label":"복수","depth":3},{"id":"reading-4","label":"2. 기본 규칙","depth":2},{"id":"reading-5","label":"대부분의 명사","depth":2},{"id":"reading-6","label":"3. -s, -x, -ch, -sh 등으로 끝나는 경우","depth":2},{"id":"reading-7","label":"4. 자음 + y","depth":2},{"id":"reading-8","label":"5. 불규칙 복수형","depth":2},{"id":"reading-9","label":"6. 단수와 복수는 동사에도 영향을 준다","depth":2},{"id":"reading-10","label":"단수","depth":3},{"id":"reading-11","label":"복수","depth":3},{"id":"reading-12","label":"7. 대명사와 연결","depth":2},{"id":"reading-13","label":"단수","depth":3},{"id":"reading-14","label":"복수","depth":3},{"id":"reading-15","label":"8. 숫자가 있으면 복수형","depth":2},{"id":"reading-16","label":"9. 아직 a/an은 완전히 배우지 않는다","depth":2},{"id":"reading-17","label":"핵심","depth":2},{"id":"reading-18","label":"하나","depth":3},{"id":"reading-19","label":"둘 이상","depth":3},{"id":"reading-20","label":"연습","depth":2}],"origin":"conversation","characters":1900,"aliases":{"structure":"concept","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-12","topic-9":"reading-15","topic-10":"reading-16","topic-11":"reading-17","topic-12":"reading-20"}},{"id":10,"title":"10단계 — 관사 a / an","html":"\u003ch1 id=\"lesson-title\" data-id=\"10\">10단계 — 관사 \u003ccode>a / an\u003c/code>\u003c/h1>\n\u003cp>이번 단계에서는 \u003cstrong>왜 단수명사 앞에 \u003ccode>a/an\u003c/code>이 필요한지\u003c/strong>부터 이해한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>a / an\u003c/code>의 핵심 의미\u003c/h2>\n\u003cp>\u003ccode>a / an\u003c/code>은 기본적으로\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>여러 개 중 하나\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻이다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>a car\u003c/strong>.\u003cbr>나는 차가 한 대 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>car\u003c/code>라는 종류의 물건 중 \u003cstrong>하나\u003c/strong>라는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 단수명사는 혼자 쓰기 어려운 경우가 많다\u003c/h2>\n\u003cp>영어에서는 \u003cstrong>셀 수 있는 단수명사\u003c/strong>를 보통 혼자 두지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I have car.\u003cbr>✅ I have \u003cstrong>a car\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ She is teacher.\u003cbr>✅ She is \u003cstrong>a teacher\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉,\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>car\u003c/code>, \u003ccode>teacher\u003c/code>, \u003ccode>book\u003c/code>처럼 \u003cstrong>하나를 셀 수 있는 명사 하나\u003c/strong>를 말할 때는 앞에 뭔가 필요하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>그중 가장 기본적인 것이 \u003ccode>a / an\u003c/code>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. \u003ccode>a\u003c/code>와 \u003ccode>an\u003c/code>의 차이\u003c/h2>\n\u003cp>뜻은 같다.\u003c/p>\n\u003cp>차이는 \u003cstrong>뒤에 오는 소리\u003c/strong>다.\u003c/p>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">자음 소리 앞\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>a\u003c/strong> dog\u003cbr>\u003cstrong>a\u003c/strong> car\u003cbr>\u003cstrong>a\u003c/strong> teacher\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">모음 소리 앞\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>an\u003c/strong> apple\u003cbr>\u003cstrong>an\u003c/strong> egg\u003cbr>\u003cstrong>an\u003c/strong> orange\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 철자가 아니라 발음이 기준\u003c/h2>\n\u003cp>이게 중요하다.\u003c/p>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">university\u003c/h3>\n\u003cp>첫 글자는 \u003ccode>u\u003c/code>지만 발음이\u003c/p>\n\u003cblockquote>\n\u003cp>유니버시티\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 \u003cstrong>y 소리\u003c/strong>로 시작한다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>a university\u003c/strong> ✅\u003cbr>an university ❌\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">hour\u003c/h3>\n\u003cp>첫 글자는 \u003ccode>h\u003c/code>지만 \u003ccode>h\u003c/code>를 발음하지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>hour → 아워\u003c/p>\n\u003c/blockquote>\n\u003cp>모음 소리로 시작하므로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>an hour\u003c/strong> ✅\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. \u003ccode>a/an\u003c/code>은 복수명사와 함께 쓰지 않는다\u003c/h2>\n\u003cp>\u003ccode>a\u003c/code> 자체가 이미 \u003cstrong>하나\u003c/strong>라는 의미를 가진다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>a book ✅\u003cbr>two books ✅\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ a books\u003cbr>❌ a dogs\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. 숫자 \u003ccode>one\u003c/code>과 \u003ccode>a\u003c/code>의 차이\u003c/h2>\n\u003cp>둘 다 하나를 뜻할 수 있지만 느낌이 다르다.\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">a\u003c/h3>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>a dog\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>그냥:\u003c/p>\n\u003cblockquote>\n\u003cp>개 한 마리 키워.\u003c/p>\n\u003c/blockquote>\n\u003cp>개수가 특별히 중요하지 않다.\u003c/p>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">one\u003c/h3>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>one dog\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>개 \u003cstrong>한 마리\u003c/strong> 키워.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>두 마리가 아니라 한 마리\u003c/code>처럼 \u003cstrong>숫자를 강조\u003c/strong>한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. 직업 앞에서도 자주 사용\u003c/h2>\n\u003cp>직업은 한 사람을 특정 종류의 사람으로 설명하는 것이므로:\u003c/p>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>a teacher\u003c/strong>.\u003cbr>He is \u003cstrong>a doctor\u003c/strong>.\u003cbr>She is \u003cstrong>an engineer\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">8. 지금까지 배운 것과 연결\u003c/h2>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">단수\u003c/h3>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>a book\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">복수\u003c/h3>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>books\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기까지 보면 이런 차이가 생긴다.\u003c/p>\n\u003cblockquote>\n\u003cp>a book\u003cbr>books\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 아직 중요한 문제가 하나 남는다.\u003c/p>\n\u003cp>왜:\u003c/p>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>coffee\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>에서는 \u003ccode>a\u003c/code>가 없고,\u003c/p>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>a car\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>에서는 \u003ccode>a\u003c/code>가 필요할까?\u003c/p>\n\u003cp>이걸 이해하려면 다음 단계에서 \u003cstrong>가산명사와 불가산명사\u003c/strong>를 배워야 한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">핵심\u003c/h2>\n\u003cp>\u003ccode>a / an\u003c/code>\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>셀 수 있는 명사 하나를 말할 때 사용하는 기본 관사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">a\u003c/h3>\n\u003cp>자음 소리 앞\u003c/p>\n\u003cblockquote>\n\u003cp>a car\u003cbr>a dog\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">an\u003c/h3>\n\u003cp>모음 소리 앞\u003c/p>\n\u003cblockquote>\n\u003cp>an apple\u003cbr>an hour\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>a apple / an apple  \u003c/li>\n\u003cli>a dog / an dog  \u003c/li>\n\u003cli>a hour / an hour  \u003c/li>\n\u003cli>a university / an university  \u003c/li>\n\u003cli>a teacher / an teacher  \u003c/li>\n\u003cli>a engineer / an engineer\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>11단계 — 가산명사와 불가산명사\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. a / an의 핵심 의미","depth":2},{"id":"reading-2","label":"2. 단수명사는 혼자 쓰기 어려운 경우가 많다","depth":2},{"id":"reading-3","label":"3. a와 an의 차이","depth":2},{"id":"reading-4","label":"자음 소리 앞","depth":3},{"id":"reading-5","label":"모음 소리 앞","depth":3},{"id":"reading-6","label":"4. 철자가 아니라 발음이 기준","depth":2},{"id":"reading-7","label":"university","depth":3},{"id":"reading-8","label":"hour","depth":3},{"id":"reading-9","label":"5. a/an은 복수명사와 함께 쓰지 않는다","depth":2},{"id":"reading-10","label":"6. 숫자 one과 a의 차이","depth":2},{"id":"reading-11","label":"a","depth":3},{"id":"reading-12","label":"one","depth":3},{"id":"reading-13","label":"7. 직업 앞에서도 자주 사용","depth":2},{"id":"reading-14","label":"8. 지금까지 배운 것과 연결","depth":2},{"id":"reading-15","label":"단수","depth":3},{"id":"reading-16","label":"복수","depth":3},{"id":"reading-17","label":"핵심","depth":2},{"id":"reading-18","label":"a","depth":3},{"id":"reading-19","label":"an","depth":3},{"id":"reading-20","label":"연습","depth":2}],"origin":"conversation","characters":1969,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-3","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-6","topic-5":"reading-9","topic-6":"reading-10","topic-7":"reading-13","topic-8":"reading-14","topic-9":"reading-17","topic-10":"reading-20","topic-11":"concept","topic-12":"concept"}},{"id":11,"title":"11단계 — 가산명사와 불가산명사","html":"\u003ch1 id=\"lesson-title\" data-id=\"11\">11단계 — 가산명사와 불가산명사\u003c/h1>\n\u003cp>이번에는 \u003cstrong>“왜 어떤 명사는 하나, 둘로 세고 어떤 명사는 그렇지 않은가”\u003c/strong>를 배운다.\u003c/p>\n\u003cp>중요한 점부터 잡자.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>a/an을 붙일 수 있나?\u003c/code>, \u003ccode>many/much 중 뭐가 맞나?\u003c/code>로 가산·불가산을 판단하는 게 아니다.\u003cbr>그건 \u003cstrong>가산·불가산을 구분한 뒤 따라오는 문법 결과\u003c/strong>다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 가산명사란?\u003c/h2>\n\u003cp>영어에서 \u003cstrong>개별적인 하나의 단위로 인식하는 명사\u003c/strong>다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>book\u003cbr>dog\u003cbr>chair\u003cbr>idea\u003cbr>problem\u003c/p>\n\u003c/blockquote>\n\u003cp>이것들은 자연스럽게:\u003c/p>\n\u003cblockquote>\n\u003cp>one book\u003cbr>two books\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>one idea\u003cbr>three ideas\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 각각을 \u003cstrong>독립된 하나\u003c/strong>로 셀 수 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 불가산명사란?\u003c/h2>\n\u003cp>영어에서 \u003cstrong>개별 하나하나보다 전체적인 물질, 양, 개념으로 보는 명사\u003c/strong>다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>water\u003cbr>milk\u003cbr>information\u003cbr>advice\u003cbr>furniture\u003c/p>\n\u003c/blockquote>\n\u003cp>이걸 영어에서는 기본적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>하나의 water\u003cbr>두 개의 information\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 보지 않는다.\u003c/p>\n\u003cp>전체적인 \u003cstrong>양\u003c/strong>으로 본다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 물질은 불가산인 경우가 많다\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>water\u003cbr>rice\u003cbr>sugar\u003cbr>milk\u003cbr>air\u003c/p>\n\u003c/blockquote>\n\u003cp>왜냐하면 영어에서는 이것들을 기본적으로 \u003cstrong>개별 물체가 아니라 물질 자체\u003c/strong>로 보기 때문이다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I need water.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>water\u003c/code>는 물 몇 개가 아니라\u003cbr>\u003cstrong>물이라는 물질의 양\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 형태가 없는 개념도 불가산인 경우가 많다\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>information = 정보\u003cbr>advice = 조언\u003cbr>knowledge = 지식\u003cbr>luck = 행운\u003c/p>\n\u003c/blockquote>\n\u003cp>한국어에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>정보 하나\u003cbr>조언 두 개\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 자연스럽게 말할 수 있지만,\u003c/p>\n\u003cp>영어에서는 \u003ccode>information\u003c/code>, \u003ccode>advice\u003c/code> 자체를 \u003cstrong>개별 조각으로 세지 않는다.\u003c/strong>\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ an information\u003cbr>✅ some information\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ two advices\u003cbr>✅ some advice\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">5. 그렇다고 “눈에 안 보이면 불가산”은 아니다\u003c/h2>\n\u003cp>이 규칙으로 판단하면 틀린다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>idea = 가산명사\u003cbr>dream = 가산명사\u003cbr>problem = 가산명사\u003c/p>\n\u003c/blockquote>\n\u003cp>눈에 보이지 않지만:\u003c/p>\n\u003cblockquote>\n\u003cp>an idea\u003cbr>two ideas\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>a problem\u003cbr>three problems\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 \u003cstrong>하나의 독립된 사건이나 개념\u003c/strong>으로 본다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">6. 반대로 눈에 보여도 불가산일 수 있다\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>furniture = 가구\u003c/p>\n\u003c/blockquote>\n\u003cp>실제로 의자, 책상, 침대는 눈에 보인다.\u003c/p>\n\u003cp>하지만 영어의 \u003ccode>furniture\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>가구라는 물품 전체\u003c/p>\n\u003c/blockquote>\n\u003cp>를 하나의 집합적인 개념으로 본다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ a furniture\u003cbr>❌ furnitures\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>✅ some furniture\u003c/p>\n\u003c/blockquote>\n\u003cp>가 된다.\u003c/p>\n\u003cp>개별적으로 세고 싶으면:\u003c/p>\n\u003cblockquote>\n\u003cp>a chair\u003cbr>two tables\u003cbr>three pieces of furniture\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 말한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">7. 가장 중요한 판단 기준\u003c/h2>\n\u003cp>새 명사를 볼 때 이렇게 생각한다.\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">① 영어가 이것을 독립된 개체로 보는가?\u003c/h3>\n\u003cblockquote>\n\u003cp>book\u003cbr>car\u003cbr>idea\u003cbr>problem\u003c/p>\n\u003c/blockquote>\n\u003cp>그렇다면 \u003cstrong>가산명사\u003c/strong>.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">② 영어가 물질·양·전체적 개념으로 보는가?\u003c/h3>\n\u003cblockquote>\n\u003cp>water\u003cbr>rice\u003cbr>information\u003cbr>furniture\u003c/p>\n\u003c/blockquote>\n\u003cp>그렇다면 \u003cstrong>불가산명사\u003c/strong>.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">그런데 이것만으로 100% 판단할 수는 없다\u003c/h2>\n\u003cp>가산·불가산은 결국 \u003cstrong>영어권에서 그 명사를 어떻게 개념화하느냐\u003c/strong>의 문제다.\u003c/p>\n\u003cp>그래서 일부 단어는 단어를 배울 때부터 같이 익혀야 한다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>advice [불가산]\u003cbr>information [불가산]\u003cbr>furniture [불가산]\u003c/p>\n\u003c/blockquote>\n\u003cp>단어 뜻만 외우는 게 아니라:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>advice = 불가산명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>까지 같이 배우는 게 좋다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">8. 문법적으로 어떤 차이가 생기나\u003c/h2>\n\u003cp>이제 결과를 보자.\u003c/p>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">가산명사 단수\u003c/h3>\n\u003cblockquote>\n\u003cp>a book\u003cbr>a car\u003cbr>an idea\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">가산명사 복수\u003c/h3>\n\u003cblockquote>\n\u003cp>books\u003cbr>cars\u003cbr>ideas\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">불가산명사\u003c/h3>\n\u003cblockquote>\n\u003cp>water\u003cbr>information\u003cbr>furniture\u003c/p>\n\u003c/blockquote>\n\u003cp>불가산명사는 기본적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ a water\u003cbr>❌ informations\u003cbr>❌ furnitures\u003c/p>\n\u003c/blockquote>\n\u003cp>처럼 쓰지 않는다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. 같은 단어가 가산과 불가산 둘 다 될 수도 있다\u003c/h2>\n\u003cp>이게 영어에서 아주 중요하다.\u003c/p>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">chicken\u003c/h3>\n\u003cp>동물 한 마리:\u003c/p>\n\u003cblockquote>\n\u003cp>a chicken\u003cbr>닭 한 마리\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>가산\u003c/strong>\u003c/p>\n\u003cp>음식으로서 닭고기:\u003c/p>\n\u003cblockquote>\n\u003cp>I ate chicken.\u003cbr>닭고기를 먹었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>불가산\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">paper\u003c/h3>\n\u003cp>종이라는 재료:\u003c/p>\n\u003cblockquote>\n\u003cp>I need some paper.\u003cbr>종이가 좀 필요해.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 불가산\u003c/p>\n\u003cp>신문이나 논문 하나:\u003c/p>\n\u003cblockquote>\n\u003cp>I read a paper.\u003cbr>논문 하나를 읽었다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 가산\u003c/p>\n\u003cp>즉, \u003cstrong>단어 자체보다 그 문장에서 어떤 의미로 쓰였는지가 중요할 때도 있다.\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">핵심\u003c/h2>\n\u003cp>가산명사:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>독립된 개체 하나하나로 보는 것\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>불가산명사:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>물질·양·전체 개념으로 보는 것\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>a/an\u003c/code>, 복수형, many/much는 \u003cstrong>판단 기준이 아니라 문법적 결과\u003c/strong>다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">연습\u003c/h2>\n\u003cp>다음 명사를 가산 / 불가산으로 나눠봐.\u003c/p>\n\u003col>\n\u003cli>book  \u003c/li>\n\u003cli>water  \u003c/li>\n\u003cli>idea  \u003c/li>\n\u003cli>information  \u003c/li>\n\u003cli>chair  \u003c/li>\n\u003cli>furniture  \u003c/li>\n\u003cli>advice  \u003c/li>\n\u003cli>problem\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>12단계 — \u003ccode>some / any\u003c/code>와 수량 표현의 기초\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 가산명사란?","depth":2},{"id":"reading-2","label":"2. 불가산명사란?","depth":2},{"id":"reading-3","label":"3. 물질은 불가산인 경우가 많다","depth":2},{"id":"reading-4","label":"4. 형태가 없는 개념도 불가산인 경우가 많다","depth":2},{"id":"reading-5","label":"5. 그렇다고 “눈에 안 보이면 불가산”은 아니다","depth":2},{"id":"reading-6","label":"6. 반대로 눈에 보여도 불가산일 수 있다","depth":2},{"id":"reading-7","label":"7. 가장 중요한 판단 기준","depth":2},{"id":"reading-8","label":"① 영어가 이것을 독립된 개체로 보는가?","depth":3},{"id":"reading-9","label":"② 영어가 물질·양·전체적 개념으로 보는가?","depth":3},{"id":"reading-10","label":"그런데 이것만으로 100% 판단할 수는 없다","depth":2},{"id":"reading-11","label":"8. 문법적으로 어떤 차이가 생기나","depth":2},{"id":"reading-12","label":"가산명사 단수","depth":3},{"id":"reading-13","label":"가산명사 복수","depth":3},{"id":"reading-14","label":"불가산명사","depth":3},{"id":"reading-15","label":"9. 같은 단어가 가산과 불가산 둘 다 될 수도 있다","depth":2},{"id":"reading-16","label":"chicken","depth":3},{"id":"reading-17","label":"paper","depth":3},{"id":"reading-18","label":"핵심","depth":2},{"id":"reading-19","label":"연습","depth":2}],"origin":"conversation","characters":2938,"aliases":{"structure":"reading-4","examples":"concept","contrast":"reading-11","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-5","topic-6":"reading-6","topic-7":"reading-7","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-15","topic-11":"reading-18","topic-12":"reading-19"}},{"id":12,"title":"12단계 — some / any","html":"\u003ch1 id=\"lesson-title\" data-id=\"12\">12단계 — \u003ccode>some / any\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003cstrong>수량이 정확하지 않을 때\u003c/strong> 쓰는 가장 기본적인 표현을 배운다.\u003c/p>\n\u003cp>핵심은 이것이다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>some = 어느 정도 있다\u003c/strong>\u003c/p>\n\u003cp>\u003cstrong>any = 있는지 없는지 열어둔다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>some\u003c/code>\u003c/h2>\n\u003cp>보통 \u003cstrong>긍정문\u003c/strong>에서 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>some books\u003c/strong>.\u003cbr>나는 책이 좀 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I need \u003cstrong>some water\u003c/strong>.\u003cbr>나는 물이 좀 필요하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>중요한 점:\u003c/p>\n\u003cp>\u003ccode>some\u003c/code>은 \u003cstrong>가산명사 복수\u003c/strong>와 \u003cstrong>불가산명사\u003c/strong> 둘 다 쓸 수 있다.\u003c/p>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">가산명사 복수\u003c/h3>\n\u003cblockquote>\n\u003cp>some books\u003cbr>some apples\u003cbr>some chairs\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">불가산명사\u003c/h3>\n\u003cblockquote>\n\u003cp>some water\u003cbr>some information\u003cbr>some advice\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 수량을 말할 때 왜 \u003ccode>some books\u003c/code>인가?\u003c/h2>\n\u003cp>\u003ccode>book\u003c/code>은 가산명사다.\u003c/p>\n\u003cp>한 권이면:\u003c/p>\n\u003cblockquote>\n\u003cp>a book\u003c/p>\n\u003c/blockquote>\n\u003cp>여러 권인데 정확한 수를 말하지 않으면:\u003c/p>\n\u003cblockquote>\n\u003cp>some books\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ some book → “책 몇 권”이라는 수량의 뜻으로는 맞지 않음\u003cbr>✅ some books\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>some book\u003c/code> 자체가 언제나 틀린 것은 아니다. “어떤 책 한 권”처럼 정확히 밝히지 않은 대상을 뜻할 때는 가능하다.\u003c/p>\n\u003cp>반면 \u003ccode>water\u003c/code>는 불가산명사라 복수형이 필요 없다.\u003c/p>\n\u003cblockquote>\n\u003cp>some water\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. \u003ccode>any\u003c/code>\u003c/h2>\n\u003cp>\u003ccode>any\u003c/code>는 주로 \u003cstrong>의문문과 부정문\u003c/strong>에서 쓴다.\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">의문문\u003c/h3>\n\u003cblockquote>\n\u003cp>Do you have \u003cstrong>any books\u003c/strong>?\u003cbr>책 있어?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Do you have \u003cstrong>any water\u003c/strong>?\u003cbr>물 있어?\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>any\u003c/code>는:\u003c/p>\n\u003cblockquote>\n\u003cp>하나라도 있는지 / 어느 정도라도 있는지\u003c/p>\n\u003c/blockquote>\n\u003cp>확인하는 느낌이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. 부정문\u003c/h2>\n\u003cblockquote>\n\u003cp>I don&#39;t have \u003cstrong>any books\u003c/strong>.\u003cbr>나는 책이 하나도 없다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I don&#39;t have \u003cstrong>any water\u003c/strong>.\u003cbr>나는 물이 전혀 없다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>not + any\u003c/p>\n\u003c/blockquote>\n\u003cp>가 만나면 보통\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>하나도 없다 / 전혀 없다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 의미가 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. 기본 패턴\u003c/h2>\n\u003cp>가장 먼저 이 세 개를 묶어서 익힌다.\u003c/p>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">긍정\u003c/h3>\n\u003cblockquote>\n\u003cp>I have \u003cstrong>some money\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">의문\u003c/h3>\n\u003cblockquote>\n\u003cp>Do you have \u003cstrong>any money\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">부정\u003c/h3>\n\u003cblockquote>\n\u003cp>I don&#39;t have \u003cstrong>any money\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">6. \u003ccode>some\u003c/code>과 \u003ccode>any\u003c/code>를 단순히 긍정/부정으로만 외우면 안 된다\u003c/h2>\n\u003cp>기본 규칙은:\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>문장\u003c/th>\n\u003cth>보통 사용\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>긍정문\u003c/td>\n\u003ctd>some\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>의문문\u003c/td>\n\u003ctd>any\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>부정문\u003c/td>\n\u003ctd>any\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>하지만 실제 의미가 더 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. 질문인데 \u003ccode>some\u003c/code>을 쓰는 경우\u003c/h2>\n\u003cp>상대방이 \u003cstrong>그렇다고 예상하거나\u003c/strong>, 무언가를 \u003cstrong>권하거나 요청할 때\u003c/strong> \u003ccode>some\u003c/code>을 쓸 수 있다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>Would you like \u003cstrong>some coffee\u003c/strong>?\u003cbr>커피 좀 드실래요?\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>some coffee\u003c/code>를 자연스럽게 쓰는 이유는\u003cbr>단순히 “커피가 있습니까?”라고 존재 여부를 묻는 게 아니라\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>커피를 드릴까요?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 제안이기 때문이다.\u003c/p>\n\u003chr>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>Can I have \u003cstrong>some water\u003c/strong>?\u003cbr>물 좀 주실 수 있어요?\u003c/p>\n\u003c/blockquote>\n\u003cp>물을 받을 것을 어느 정도 기대하면서 요청한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">8. \u003ccode>any\u003c/code>가 긍정문에 나오는 경우\u003c/h2>\n\u003cp>조금 뒤 단계에서 자세히 배우겠지만, \u003ccode>any\u003c/code>는 긍정문에서:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>어떤 것이든 / 아무거나\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 뜻도 가진다.\u003c/p>\n\u003cblockquote>\n\u003cp>You can choose \u003cstrong>any book\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>어떤 책이든 골라도 돼.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 \u003ccode>any book\u003c/code>처럼 \u003cstrong>단수명사\u003c/strong>도 올 수 있다.\u003c/p>\n\u003cp>이것은 지금 배우는 “수량 표현 any”와 의미가 조금 다르므로\u003cbr>지금은 구별만 해두면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. 지금까지 연결\u003c/h2>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">가산 단수\u003c/h3>\n\u003cblockquote>\n\u003cp>a book\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">가산 복수\u003c/h3>\n\u003cblockquote>\n\u003cp>books\u003cbr>some books\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">불가산\u003c/h3>\n\u003cblockquote>\n\u003cp>water\u003cbr>some water\u003c/p>\n\u003c/blockquote>\n\u003cp>그리고 질문이나 부정에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>any books\u003cbr>any water\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">핵심\u003c/h2>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">\u003ccode>some\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>어느 정도 존재한다고 보는 표현\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I have some friends.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">\u003ccode>any\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>존재 여부를 열어두거나 부정하는 표현\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Do you have any friends?\u003cbr>I don&#39;t have any friends.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">연습\u003c/h2>\n\u003cp>\u003ccode>some / any\u003c/code> 중 문맥에 맞는 것을 넣어봐. 3번처럼 둘 다 가능한 질문은 도움을 제안하는지, 필요 여부를 중립적으로 묻는지도 생각해봐.\u003c/p>\n\u003col>\n\u003cli>I have ___ books.\u003c/li>\n\u003cli>I don&#39;t have ___ money.\u003c/li>\n\u003cli>Do you need ___ help?\u003c/li>\n\u003cli>She bought ___ apples.\u003c/li>\n\u003cli>We don&#39;t have ___ information.\u003c/li>\n\u003cli>Would you like ___ coffee?\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>13단계 — \u003ccode>the\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. some","depth":2},{"id":"reading-2","label":"가산명사 복수","depth":3},{"id":"reading-3","label":"불가산명사","depth":3},{"id":"reading-4","label":"2. 수량을 말할 때 왜 some books인가?","depth":2},{"id":"reading-5","label":"3. any","depth":2},{"id":"reading-6","label":"의문문","depth":3},{"id":"reading-7","label":"4. 부정문","depth":2},{"id":"reading-8","label":"5. 기본 패턴","depth":2},{"id":"reading-9","label":"긍정","depth":3},{"id":"reading-10","label":"의문","depth":3},{"id":"reading-11","label":"부정","depth":3},{"id":"reading-12","label":"6. some과 any를 단순히 긍정/부정으로만 외우면 안 된다","depth":2},{"id":"reading-13","label":"7. 질문인데 some을 쓰는 경우","depth":2},{"id":"reading-14","label":"8. any가 긍정문에 나오는 경우","depth":2},{"id":"reading-15","label":"9. 지금까지 연결","depth":2},{"id":"reading-16","label":"가산 단수","depth":3},{"id":"reading-17","label":"가산 복수","depth":3},{"id":"reading-18","label":"불가산","depth":3},{"id":"reading-19","label":"핵심","depth":2},{"id":"reading-20","label":"some","depth":3},{"id":"reading-21","label":"any","depth":3},{"id":"reading-22","label":"연습","depth":2}],"origin":"conversation","characters":2548,"aliases":{"structure":"concept","examples":"concept","contrast":"concept","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-7","topic-5":"reading-8","topic-6":"reading-12","topic-7":"reading-13","topic-8":"reading-14","topic-9":"reading-15","topic-10":"reading-19","topic-11":"reading-22","topic-12":"concept"}},{"id":13,"title":"13단계 — 정관사 the","html":"\u003ch1 id=\"lesson-title\" data-id=\"13\">13단계 — 정관사 \u003ccode>the\u003c/code>\u003c/h1>\n\u003cp>이번에는 \u003ccode>a/an\u003c/code>과 자주 비교되는 \u003cstrong>\u003ccode>the\u003c/code>\u003c/strong>를 배운다.\u003c/p>\n\u003cp>핵심은 하나다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>the = 말하는 사람과 듣는 사람이 어떤 것을 말하는지 알 수 있을 때\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>a/an\u003c/code>과 \u003ccode>the\u003c/code>의 차이\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">\u003ccode>a/an\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>여러 개 중 \u003cstrong>아무거나 하나\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I saw \u003cstrong>a dog\u003c/strong>.\u003cbr>나는 개 한 마리를 봤다.\u003c/p>\n\u003c/blockquote>\n\u003cp>어떤 개인지는 아직 중요하지 않다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">\u003ccode>the\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>서로 \u003cstrong>어떤 것인지 알고 있는 그 대상\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>The dog\u003c/strong> was very cute.\u003cbr>그 개는 아주 귀여웠다.\u003c/p>\n\u003c/blockquote>\n\u003cp>앞에서 이미 \u003ccode>a dog\u003c/code>이라고 말했기 때문에\u003cbr>이제 어떤 개인지 서로 알고 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 처음에는 \u003ccode>a\u003c/code>, 두 번째에는 \u003ccode>the\u003c/code>\u003c/h2>\n\u003cp>가장 기본적인 패턴이다.\u003c/p>\n\u003cblockquote>\n\u003cp>I bought \u003cstrong>a book\u003c/strong>.\u003cbr>\u003cstrong>The book\u003c/strong> is interesting.\u003c/p>\n\u003c/blockquote>\n\u003cp>처음:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>a book\u003c/code> = 책 한 권\u003c/p>\n\u003c/blockquote>\n\u003cp>두 번째:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>the book\u003c/code> = 아까 말한 그 책\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 상황상 어떤 것인지 알 때\u003c/h2>\n\u003cp>앞에서 말하지 않았어도 서로 어떤 대상을 말하는지 알 수 있다.\u003c/p>\n\u003cp>예를 들어 방 안에 문이 하나 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>Close \u003cstrong>the door\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>문 닫아.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>a door\u003c/code>가 아닌 이유는\u003cbr>듣는 사람도 \u003cstrong>어느 문인지 알고 있기 때문\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>Turn off \u003cstrong>the light\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>방 안에 있는 그 불을 끄라는 의미다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 세상에 하나라고 보는 것\u003c/h2>\n\u003cp>대표적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>the sun\u003cbr>the moon\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>The sun\u003c/strong> is hot.\u003c/p>\n\u003c/blockquote>\n\u003cp>태양이 여러 개 중 하나라는 의미가 아니라\u003cbr>우리가 알고 있는 \u003cstrong>그 태양\u003c/strong>이므로 \u003ccode>the\u003c/code>를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>the\u003c/code>는 단수에도, 복수에도 쓸 수 있다\u003c/h2>\n\u003cp>이게 \u003ccode>a/an\u003c/code>과 큰 차이다.\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">단수\u003c/h3>\n\u003cblockquote>\n\u003cp>the book\u003cbr>the car\u003cbr>the teacher\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-9\" data-reading-anchor=\"reading-9\">복수\u003c/h3>\n\u003cblockquote>\n\u003cp>the books\u003cbr>the cars\u003cbr>the students\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">6. 불가산명사에도 쓸 수 있다\u003c/h2>\n\u003cblockquote>\n\u003cp>water\u003c/p>\n\u003c/blockquote>\n\u003cp>그냥 일반적인 물:\u003c/p>\n\u003cblockquote>\n\u003cp>I drink water.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 특정한 물:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>The water\u003c/strong> in this bottle is cold.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>이 병 안의 \u003cstrong>그 물\u003c/strong>은 차갑다.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉 \u003ccode>the\u003c/code>는 가산/불가산보다 \u003cstrong>특정성\u003c/strong>이 핵심이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">7. 비교\u003c/h2>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">일반적인 대상\u003c/h3>\n\u003cblockquote>\n\u003cp>I like dogs.\u003cbr>나는 개를 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>개라는 종류 전체.\u003c/p>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">특정한 대상\u003c/h3>\n\u003cblockquote>\n\u003cp>I like \u003cstrong>the dogs\u003c/strong> in this park.\u003cbr>나는 이 공원에 있는 \u003cstrong>그 개들\u003c/strong>을 좋아한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">일반적인 물질\u003c/h3>\n\u003cblockquote>\n\u003cp>I need water.\u003cbr>나는 물이 필요하다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">특정한 물\u003c/h3>\n\u003cblockquote>\n\u003cp>I need \u003cstrong>the water\u003c/strong> on the table.\u003cbr>나는 탁자 위에 있는 \u003cstrong>그 물\u003c/strong>이 필요하다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">8. \u003ccode>a/an\u003c/code>과 \u003ccode>the\u003c/code>\u003c/h2>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">처음 등장\u003c/h3>\n\u003cblockquote>\n\u003cp>I saw \u003cstrong>a man\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>어떤 남자인지 듣는 사람은 모른다.\u003c/p>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">다시 등장\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>The man\u003c/strong> was tall.\u003c/p>\n\u003c/blockquote>\n\u003cp>이제는 아까 말한 남자라는 걸 안다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">9. 아주 중요한 감각\u003c/h2>\n\u003cp>\u003ccode>the\u003c/code>를 단순히\u003c/p>\n\u003cblockquote>\n\u003cp>“그”\u003c/p>\n\u003c/blockquote>\n\u003cp>라고만 외우면 부족하다.\u003c/p>\n\u003cp>더 정확하게는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>너도 내가 무엇을 말하는지 알지?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 전제가 있는 표현이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">핵심\u003c/h2>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">\u003ccode>a/an\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>여러 개 중 \u003cstrong>하나\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-22\" data-reading-anchor=\"reading-22\">\u003ccode>the\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>서로 \u003cstrong>어떤 것인지 알 수 있는 특정 대상\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-23\" data-reading-anchor=\"reading-23\">무관사\u003c/h3>\n\u003cblockquote>\n\u003cp>종류 전체나 일반적인 개념을 말할 때 자주 사용\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I like dogs.\u003cbr>I need water.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">연습\u003c/h2>\n\u003cp>\u003ccode>a / an / the\u003c/code> 중 맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I saw ___ dog. ___ dog was very cute.\u003c/li>\n\u003cli>Please close ___ door.\u003c/li>\n\u003cli>I bought ___ apple.\u003c/li>\n\u003cli>___ apple was sweet.\u003c/li>\n\u003cli>___ sun is very bright today.\u003c/li>\n\u003cli>I need ___ water on the table.\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>14단계 — 형용사\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. a/an과 the의 차이","depth":2},{"id":"reading-2","label":"a/an","depth":3},{"id":"reading-3","label":"the","depth":3},{"id":"reading-4","label":"2. 처음에는 a, 두 번째에는 the","depth":2},{"id":"reading-5","label":"3. 상황상 어떤 것인지 알 때","depth":2},{"id":"reading-6","label":"4. 세상에 하나라고 보는 것","depth":2},{"id":"reading-7","label":"5. the는 단수에도, 복수에도 쓸 수 있다","depth":2},{"id":"reading-8","label":"단수","depth":3},{"id":"reading-9","label":"복수","depth":3},{"id":"reading-10","label":"6. 불가산명사에도 쓸 수 있다","depth":2},{"id":"reading-11","label":"7. 비교","depth":2},{"id":"reading-12","label":"일반적인 대상","depth":3},{"id":"reading-13","label":"특정한 대상","depth":3},{"id":"reading-14","label":"일반적인 물질","depth":3},{"id":"reading-15","label":"특정한 물","depth":3},{"id":"reading-16","label":"8. a/an과 the","depth":2},{"id":"reading-17","label":"처음 등장","depth":3},{"id":"reading-18","label":"다시 등장","depth":3},{"id":"reading-19","label":"9. 아주 중요한 감각","depth":2},{"id":"reading-20","label":"핵심","depth":2},{"id":"reading-21","label":"a/an","depth":3},{"id":"reading-22","label":"the","depth":3},{"id":"reading-23","label":"무관사","depth":3},{"id":"reading-24","label":"연습","depth":2}],"origin":"conversation","characters":2176,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-1","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-10","topic-7":"reading-11","topic-8":"reading-16","topic-9":"reading-19","topic-10":"reading-20","topic-11":"reading-24","topic-12":"concept"}},{"id":14,"title":"14단계 — 형용사(Adjective)","html":"\u003ch1 id=\"lesson-title\" data-id=\"14\">14단계 — 형용사(Adjective)\u003c/h1>\n\u003cp>형용사는 \u003cstrong>명사가 어떤 상태인지, 어떤 특징이 있는지 설명하는 말\u003c/strong>이다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cul>\n\u003cli>big = 큰\u003c/li>\n\u003cli>small = 작은\u003c/li>\n\u003cli>happy = 행복한\u003c/li>\n\u003cli>tired = 피곤한\u003c/li>\n\u003cli>beautiful = 아름다운\u003c/li>\n\u003cli>expensive = 비싼\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 형용사의 가장 기본적인 두 자리\u003c/h2>\n\u003cp>영어에서 형용사는 크게 두 곳에 온다.\u003c/p>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">① 명사 앞\u003c/h3>\n\u003cblockquote>\n\u003cp>a \u003cstrong>big\u003c/strong> car\u003cbr>큰 차\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>a \u003cstrong>beautiful\u003c/strong> house\u003cbr>아름다운 집\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>형용사 + 명사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>영어는 한국어와 비슷하게 형용사가 명사 앞에 올 수 있다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">② be동사 뒤\u003c/h3>\n\u003cblockquote>\n\u003cp>The car is \u003cstrong>big\u003c/strong>.\u003cbr>그 차는 크다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>happy\u003c/strong>.\u003cbr>그녀는 행복하다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + be동사 + 형용사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 둘은 같은 형용사다\u003c/h2>\n\u003cblockquote>\n\u003cp>a \u003cstrong>small\u003c/strong> dog\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>small\u003c/code>은 \u003ccode>dog\u003c/code>를 설명한다.\u003c/p>\n\u003cblockquote>\n\u003cp>The dog is \u003cstrong>small\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서도 \u003ccode>small\u003c/code>은 \u003ccode>dog\u003c/code>를 설명한다.\u003c/p>\n\u003cp>차이는 \u003cstrong>위치\u003c/strong>뿐이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 일반동사 뒤에 바로 형용사를 붙이면 안 되는 경우가 많다\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I work tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>tired\u003c/code>는 \u003ccode>I\u003c/code>의 상태를 설명하는 형용사다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I am tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>I work hard.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 \u003ccode>hard\u003c/code>는 \u003ccode>work\u003c/code>를 설명하므로 역할이 다르다.\u003cbr>이건 나중에 \u003cstrong>부사\u003c/strong>에서 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 형용사는 복수형이 없다\u003c/h2>\n\u003cp>명사는 복수형이 있다.\u003c/p>\n\u003cblockquote>\n\u003cp>a big dog\u003cbr>two big dogs\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 형용사는:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ bigs dogs\u003cbr>✅ big dogs\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>big\u003c/code>은 그대로다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 형용사는 주어가 바뀌어도 형태가 안 바뀐다\u003c/h2>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>tired\u003c/strong>.\u003cbr>She is \u003cstrong>tired\u003c/strong>.\u003cbr>They are \u003cstrong>tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>tired\u003c/code>는 그대로다.\u003c/p>\n\u003cp>바뀌는 것은 be동사다.\u003c/p>\n\u003cblockquote>\n\u003cp>am / is / are\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 형용사와 명사의 차이\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>beauty = 아름다움 → 명사\u003cbr>beautiful = 아름다운 → 형용사\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>danger = 위험 → 명사\u003cbr>dangerous = 위험한 → 형용사\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>happiness = 행복 → 명사\u003cbr>happy = 행복한 → 형용사\u003c/p>\n\u003c/blockquote>\n\u003cp>문장에서:\u003c/p>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>happy\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>happy\u003c/code>는 그녀의 상태를 설명하므로 형용사다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 지금까지 배운 구조와 연결\u003c/h2>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">명사 앞\u003c/h3>\n\u003cblockquote>\n\u003cp>I have a \u003cstrong>new car\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>I = 주어\u003c/li>\n\u003cli>have = 동사\u003c/li>\n\u003cli>a new car = 목적어\u003c/li>\n\u003cli>new = 형용사\u003c/li>\n\u003cli>car = 명사\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">be동사 뒤\u003c/h3>\n\u003cblockquote>\n\u003cp>My car is \u003cstrong>new\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cul>\n\u003cli>My car = 주어\u003c/li>\n\u003cli>is = be동사\u003c/li>\n\u003cli>new = 형용사\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">핵심\u003c/h2>\n\u003cp>형용사는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>명사를 설명한다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>대표적인 두 위치:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>형용사 + 명사\u003c/strong>\u003cbr>a big house\u003c/p>\n\u003c/blockquote>\n\u003cp>또는\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be동사 + 형용사\u003c/strong>\u003cbr>The house is big.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">연습\u003c/h2>\n\u003cp>다음 문장에서 \u003cstrong>형용사만\u003c/strong> 찾아봐.\u003c/p>\n\u003col>\n\u003cli>She is happy.\u003c/li>\n\u003cli>I have a new phone.\u003c/li>\n\u003cli>The dog is small.\u003c/li>\n\u003cli>He bought an expensive car.\u003c/li>\n\u003cli>The children are tired.\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>15단계 — 부사(Adverb)\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 형용사의 가장 기본적인 두 자리","depth":2},{"id":"reading-2","label":"① 명사 앞","depth":3},{"id":"reading-3","label":"② be동사 뒤","depth":3},{"id":"reading-4","label":"2. 둘은 같은 형용사다","depth":2},{"id":"reading-5","label":"3. 일반동사 뒤에 바로 형용사를 붙이면 안 되는 경우가 많다","depth":2},{"id":"reading-6","label":"4. 형용사는 복수형이 없다","depth":2},{"id":"reading-7","label":"5. 형용사는 주어가 바뀌어도 형태가 안 바뀐다","depth":2},{"id":"reading-8","label":"6. 형용사와 명사의 차이","depth":2},{"id":"reading-9","label":"7. 지금까지 배운 구조와 연결","depth":2},{"id":"reading-10","label":"명사 앞","depth":3},{"id":"reading-11","label":"be동사 뒤","depth":3},{"id":"reading-12","label":"핵심","depth":2},{"id":"reading-13","label":"연습","depth":2}],"origin":"conversation","characters":1803,"aliases":{"structure":"reading-7","examples":"concept","contrast":"reading-8","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-12","topic-9":"reading-13","topic-10":"concept","topic-11":"concept","topic-12":"concept"}},{"id":15,"title":"15단계 — 부사(Adverb)","html":"\u003ch1 id=\"lesson-title\" data-id=\"15\">15단계 — 부사(Adverb)\u003c/h1>\n\u003cp>형용사가 \u003cstrong>명사\u003c/strong>를 설명한다면, 부사는 주로 \u003cstrong>동사·형용사·다른 부사\u003c/strong>를 설명한다.\u003c/p>\n\u003cp>가장 먼저 \u003cstrong>동사를 설명하는 부사\u003c/strong>부터 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 형용사와 부사의 차이\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">형용사\u003c/h3>\n\u003cp>명사를 설명\u003c/p>\n\u003cblockquote>\n\u003cp>a \u003cstrong>slow\u003c/strong> car\u003cbr>느린 차\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>slow\u003c/code>가 \u003ccode>car\u003c/code>를 설명한다.\u003c/p>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">부사\u003c/h3>\n\u003cp>동작을 설명\u003c/p>\n\u003cblockquote>\n\u003cp>The car moves \u003cstrong>slowly\u003c/strong>.\u003cbr>그 차는 천천히 움직인다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>slowly\u003c/code>가 \u003ccode>moves\u003c/code>를 설명한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 동사 + 부사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She speaks \u003cstrong>slowly\u003c/strong>.\u003cbr>그녀는 천천히 말한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He works \u003cstrong>hard\u003c/strong>.\u003cbr>그는 열심히 일한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They run \u003cstrong>quickly\u003c/strong>.\u003cbr>그들은 빠르게 달린다.\u003c/p>\n\u003c/blockquote>\n\u003cp>부사는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>어떻게 행동하는지\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 설명한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. \u003ccode>-ly\u003c/code>가 붙는 경우가 많다\u003c/h2>\n\u003cp>많은 형용사는 \u003ccode>-ly\u003c/code>를 붙이면 부사가 된다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>형용사\u003c/th>\n\u003cth>부사\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>slow\u003c/td>\n\u003ctd>slowly\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>quick\u003c/td>\n\u003ctd>quickly\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>careful\u003c/td>\n\u003ctd>carefully\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>quiet\u003c/td>\n\u003ctd>quietly\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>easy\u003c/td>\n\u003ctd>easily\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>careful\u003c/strong>.\u003cbr>그녀는 조심스럽다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She drives \u003cstrong>carefully\u003c/strong>.\u003cbr>그녀는 조심스럽게 운전한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 형용사와 부사의 위치\u003c/h2>\n\u003cp>비교하면 명확하다.\u003c/p>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">형용사\u003c/h3>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>quiet\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>quiet\u003c/code>은 \u003ccode>she\u003c/code>의 상태를 설명한다.\u003c/p>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">부사\u003c/h3>\n\u003cblockquote>\n\u003cp>She speaks \u003cstrong>quietly\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>quietly\u003c/code>는 \u003ccode>speaks\u003c/code>라는 행동을 설명한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">5. \u003ccode>good\u003c/code>과 \u003ccode>well\u003c/code>\u003c/h2>\n\u003cp>아주 중요하다.\u003c/p>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">good\u003c/h3>\n\u003cp>형용사\u003c/p>\n\u003cblockquote>\n\u003cp>He is a \u003cstrong>good\u003c/strong> singer.\u003cbr>그는 좋은 가수다.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">well\u003c/h3>\n\u003cp>부사\u003c/p>\n\u003cblockquote>\n\u003cp>He sings \u003cstrong>well\u003c/strong>.\u003cbr>그는 노래를 잘한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>따라서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ He sings good.\u003cbr>✅ He sings well.\u003c/p>\n\u003c/blockquote>\n\u003cp>표준 문법에서는 이렇게 구분한다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-12\" data-reading-anchor=\"reading-12\">6. 모든 부사가 \u003ccode>-ly\u003c/code>로 끝나는 것은 아니다\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>fast\u003cbr>hard\u003cbr>well\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">fast\u003c/h3>\n\u003cblockquote>\n\u003cp>a \u003cstrong>fast\u003c/strong> car\u003cbr>빠른 차\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 형용사.\u003c/p>\n\u003cblockquote>\n\u003cp>The car moves \u003cstrong>fast\u003c/strong>.\u003cbr>차가 빠르게 움직인다.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서는 부사.\u003c/p>\n\u003cp>형태가 같다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">hard\u003c/h3>\n\u003cblockquote>\n\u003cp>This is a \u003cstrong>hard\u003c/strong> job.\u003cbr>이것은 힘든 일이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>형용사.\u003c/p>\n\u003cblockquote>\n\u003cp>I work \u003cstrong>hard\u003c/strong>.\u003cbr>나는 열심히 일한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>부사.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">7. \u003ccode>hardly\u003c/code>는 \u003ccode>hard\u003c/code>의 단순한 부사형이 아니다\u003c/h2>\n\u003cp>이건 함께 움직이는 표현처럼 \u003cstrong>별개의 의미로 외워야 한다.\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>hard = 열심히\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>hardly = 거의 ~않다\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I work \u003cstrong>hard\u003c/strong>.\u003cbr>나는 열심히 일한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I \u003cstrong>hardly\u003c/strong> work.\u003cbr>나는 거의 일하지 않는다.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻이 완전히 다르다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">8. 부사가 형용사를 설명하기도 한다\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>very tired\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>tired\u003c/code> = 형용사\u003cbr>\u003ccode>very\u003c/code> = 부사\u003c/p>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>very tired\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>very\u003c/code>가 \u003ccode>tired\u003c/code>의 정도를 설명한다.\u003c/p>\n\u003cp>또:\u003c/p>\n\u003cblockquote>\n\u003cp>really good\u003cbr>very expensive\u003cbr>too hot\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">9. 부사의 위치는 종류에 따라 달라진다\u003c/h2>\n\u003cp>지금 단계에서는 우선:\u003c/p>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">행동 방식\u003c/h3>\n\u003cblockquote>\n\u003cp>She speaks \u003cstrong>slowly\u003c/strong>.\u003cbr>He drives \u003cstrong>carefully\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>대체로 동사 뒤에 둔다.\u003c/p>\n\u003cp>하지만:\u003c/p>\n\u003cblockquote>\n\u003cp>always\u003cbr>usually\u003cbr>often\u003cbr>still\u003cbr>already\u003c/p>\n\u003c/blockquote>\n\u003cp>같은 부사는 위치 규칙이 다르다.\u003c/p>\n\u003cp>이건 뒤에서 \u003cstrong>빈도부사와 위치\u003c/strong>를 별도로 배운다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">핵심\u003c/h2>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">형용사\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>명사나 주어의 상태를 설명\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>a careful driver\u003cbr>He is careful.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">부사\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>행동이 어떻게 이루어지는지 설명\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He drives carefully.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>She is \u003cstrong>quiet / quietly\u003c/strong>.\u003c/li>\n\u003cli>She speaks \u003cstrong>quiet / quietly\u003c/strong>.\u003c/li>\n\u003cli>He is a \u003cstrong>good / well\u003c/strong> driver.\u003c/li>\n\u003cli>He drives \u003cstrong>good / well\u003c/strong>.\u003c/li>\n\u003cli>They work \u003cstrong>hard / hardly\u003c/strong> every day.\u003c/li>\n\u003cli>The car is \u003cstrong>slow / slowly\u003c/strong>.\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>16단계 — 현재시제(Simple Present)의 의미와 사용법\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 형용사와 부사의 차이","depth":2},{"id":"reading-2","label":"형용사","depth":3},{"id":"reading-3","label":"부사","depth":3},{"id":"reading-4","label":"2. 기본 구조","depth":2},{"id":"reading-5","label":"3. -ly가 붙는 경우가 많다","depth":2},{"id":"reading-6","label":"4. 형용사와 부사의 위치","depth":2},{"id":"reading-7","label":"형용사","depth":3},{"id":"reading-8","label":"부사","depth":3},{"id":"reading-9","label":"5. good과 well","depth":2},{"id":"reading-10","label":"good","depth":3},{"id":"reading-11","label":"well","depth":3},{"id":"reading-12","label":"6. 모든 부사가 -ly로 끝나는 것은 아니다","depth":2},{"id":"reading-13","label":"fast","depth":3},{"id":"reading-14","label":"hard","depth":3},{"id":"reading-15","label":"7. hardly는 hard의 단순한 부사형이 아니다","depth":2},{"id":"reading-16","label":"8. 부사가 형용사를 설명하기도 한다","depth":2},{"id":"reading-17","label":"9. 부사의 위치는 종류에 따라 달라진다","depth":2},{"id":"reading-18","label":"행동 방식","depth":3},{"id":"reading-19","label":"핵심","depth":2},{"id":"reading-20","label":"형용사","depth":3},{"id":"reading-21","label":"부사","depth":3},{"id":"reading-22","label":"연습","depth":2}],"origin":"conversation","characters":2443,"aliases":{"structure":"reading-4","examples":"concept","contrast":"reading-1","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-9","topic-6":"reading-12","topic-7":"reading-15","topic-8":"reading-16","topic-9":"reading-17","topic-10":"reading-19","topic-11":"reading-22","topic-12":"concept"}},{"id":16,"title":"16단계 — 현재시제(Simple Present)","html":"\u003ch1 id=\"lesson-title\" data-id=\"16\">16단계 — 현재시제(Simple Present)\u003c/h1>\n\u003cp>현재시제는 \u003cstrong>지금 이 순간만\u003c/strong> 말하는 시제가 아니다.\u003c/p>\n\u003cp>핵심은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>평소에 그렇다 / 반복해서 한다 / 일반적으로 사실이다\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 현재시제의 기본 용도\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">① 습관\u003c/h3>\n\u003cblockquote>\n\u003cp>I drink coffee every morning.\u003cbr>나는 매일 아침 커피를 마신다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She goes to work at 8.\u003cbr>그녀는 8시에 출근한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">② 반복되는 행동\u003c/h3>\n\u003cblockquote>\n\u003cp>We eat out on weekends.\u003cbr>우리는 주말마다 외식한다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>He calls his mother every day.\u003cbr>그는 매일 어머니에게 전화한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">③ 일반적인 사실\u003c/h3>\n\u003cblockquote>\n\u003cp>The sun rises in the east.\u003cbr>해는 동쪽에서 뜬다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>Water boils at 100°C.\u003cbr>물은 100도에서 끓는다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">④ 비교적 지속되는 상태\u003c/h3>\n\u003cblockquote>\n\u003cp>I live in Busan.\u003cbr>나는 부산에 산다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She works at a hospital.\u003cbr>그녀는 병원에서 일한다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">2. 현재시제의 기본 형태\u003c/h2>\n\u003ch3 id=\"reading-7\" data-reading-anchor=\"reading-7\">I / You / We / They\u003c/h3>\n\u003cblockquote>\n\u003cp>I work.\u003cbr>You work.\u003cbr>We work.\u003cbr>They work.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-8\" data-reading-anchor=\"reading-8\">He / She / It\u003c/h3>\n\u003cblockquote>\n\u003cp>He work\u003cstrong>s\u003c/strong>.\u003cbr>She work\u003cstrong>s\u003c/strong>.\u003cbr>It work\u003cstrong>s\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>앞에서 배운 \u003cstrong>3인칭 단수 -s\u003c/strong>가 여기서 쓰인다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">3. 자주 쓰는 시간 표현\u003c/h2>\n\u003cp>현재시제와 자주 같이 쓰인다.\u003c/p>\n\u003cul>\n\u003cli>every day\u003c/li>\n\u003cli>every morning\u003c/li>\n\u003cli>every week\u003c/li>\n\u003cli>on Mondays\u003c/li>\n\u003cli>usually\u003c/li>\n\u003cli>often\u003c/li>\n\u003cli>sometimes\u003c/li>\n\u003cli>always\u003c/li>\n\u003c/ul>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I exercise every day.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She usually drinks tea.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">4. 현재시제는 “지금 하고 있다”와 다르다\u003c/h2>\n\u003cp>이 차이가 중요하다.\u003c/p>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">현재시제\u003c/h3>\n\u003cblockquote>\n\u003cp>I eat breakfast at 7.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 보통 7시에 아침을 먹는다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">지금 먹는 중\u003c/h3>\n\u003cblockquote>\n\u003cp>I am eating breakfast now.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 지금 아침을 먹고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>am eating\u003c/code>은 나중에 \u003cstrong>현재진행형\u003c/strong>에서 배운다.\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>현재시제 = 평소\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>\u003cstrong>현재진행형 = 지금 진행 중\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">5. 부정문\u003c/h2>\n\u003cp>앞에서 배운 구조 그대로다.\u003c/p>\n\u003ch3 id=\"reading-14\" data-reading-anchor=\"reading-14\">I / You / We / They\u003c/h3>\n\u003cblockquote>\n\u003cp>I don&#39;t work on Sundays.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">He / She / It\u003c/h3>\n\u003cblockquote>\n\u003cp>She doesn&#39;t work on Sundays.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>doesn&#39;t\u003c/code> 뒤에는 동사원형:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ She doesn&#39;t works.\u003cbr>✅ She doesn&#39;t work.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">6. 의문문\u003c/h2>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">I / You / We / They\u003c/h3>\n\u003cblockquote>\n\u003cp>Do you work here?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">He / She / It\u003c/h3>\n\u003cblockquote>\n\u003cp>Does he work here?\u003c/p>\n\u003c/blockquote>\n\u003cp>역시 \u003ccode>does\u003c/code> 뒤에는 동사원형:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Does he works here?\u003cbr>✅ Does he work here?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">7. be동사의 현재시제\u003c/h2>\n\u003cp>be동사도 현재시제다.\u003c/p>\n\u003cblockquote>\n\u003cp>I am tired.\u003cbr>She is busy.\u003cbr>They are at home.\u003c/p>\n\u003c/blockquote>\n\u003cp>다만 일반동사와 형태가 다르다.\u003c/p>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">일반동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I work.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">be동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I am tired.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">8. 현재시제의 핵심 감각\u003c/h2>\n\u003cp>다음 두 문장을 비교해봐.\u003c/p>\n\u003cblockquote>\n\u003cp>I work in Busan.\u003c/p>\n\u003c/blockquote>\n\u003cp>이건:\u003c/p>\n\u003cblockquote>\n\u003cp>부산에서 일하는 사람이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 \u003cstrong>일반적 사실\u003c/strong>에 가깝다.\u003c/p>\n\u003cp>반면:\u003c/p>\n\u003cblockquote>\n\u003cp>I am working in Busan.\u003c/p>\n\u003c/blockquote>\n\u003cp>이건:\u003c/p>\n\u003cblockquote>\n\u003cp>지금 현재 부산에서 일하고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>라는 \u003cstrong>현재 진행 상황\u003c/strong>에 더 가깝다.\u003c/p>\n\u003cp>이 차이는 매우 중요하다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-23\" data-reading-anchor=\"reading-23\">핵심\u003c/h2>\n\u003cp>현재시제는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>습관 / 반복 / 일반적 사실 / 지속적 상태\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 표현한다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>I/You/We/They + 동사원형\u003cbr>He/She/It + 동사-s\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-24\" data-reading-anchor=\"reading-24\">연습\u003c/h2>\n\u003cp>현재시제로 맞는 문장을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I \u003cstrong>work / am working\u003c/strong> at a construction company.\u003cbr>→ 평소 직장을 말할 때\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She \u003cstrong>drinks / is drinking\u003c/strong> coffee every morning.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He \u003cstrong>go / goes\u003c/strong> to school at 8.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>They \u003cstrong>doesn&#39;t / don&#39;t\u003c/strong> work on Sundays.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>Does / Do\u003c/strong> she like coffee?\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>17단계 — 빈도부사 \u003ccode>always / usually / often / sometimes / never\u003c/code>와 위치\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 현재시제의 기본 용도","depth":2},{"id":"reading-2","label":"① 습관","depth":3},{"id":"reading-3","label":"② 반복되는 행동","depth":3},{"id":"reading-4","label":"③ 일반적인 사실","depth":3},{"id":"reading-5","label":"④ 비교적 지속되는 상태","depth":3},{"id":"reading-6","label":"2. 현재시제의 기본 형태","depth":2},{"id":"reading-7","label":"I / You / We / They","depth":3},{"id":"reading-8","label":"He / She / It","depth":3},{"id":"reading-9","label":"3. 자주 쓰는 시간 표현","depth":2},{"id":"reading-10","label":"4. 현재시제는 “지금 하고 있다”와 다르다","depth":2},{"id":"reading-11","label":"현재시제","depth":3},{"id":"reading-12","label":"지금 먹는 중","depth":3},{"id":"reading-13","label":"5. 부정문","depth":2},{"id":"reading-14","label":"I / You / We / They","depth":3},{"id":"reading-15","label":"He / She / It","depth":3},{"id":"reading-16","label":"6. 의문문","depth":2},{"id":"reading-17","label":"I / You / We / They","depth":3},{"id":"reading-18","label":"He / She / It","depth":3},{"id":"reading-19","label":"7. be동사의 현재시제","depth":2},{"id":"reading-20","label":"일반동사","depth":3},{"id":"reading-21","label":"be동사","depth":3},{"id":"reading-22","label":"8. 현재시제의 핵심 감각","depth":2},{"id":"reading-23","label":"핵심","depth":2},{"id":"reading-24","label":"연습","depth":2}],"origin":"conversation","characters":2431,"aliases":{"structure":"reading-6","examples":"concept","contrast":"reading-5","topic-1":"reading-1","topic-2":"reading-6","topic-3":"reading-9","topic-4":"reading-10","topic-5":"reading-13","topic-6":"reading-16","topic-7":"reading-19","topic-8":"reading-22","topic-9":"reading-23","topic-10":"reading-24","topic-11":"concept","topic-12":"concept"}},{"id":17,"title":"17단계 — 빈도부사 always / usually / often / sometimes / never","html":"\u003ch1 id=\"lesson-title\" data-id=\"17\">17단계 — 빈도부사 \u003ccode>always / usually / often / sometimes / never\u003c/code>\u003c/h1>\n\u003cp>빈도부사는 \u003cstrong>얼마나 자주 하는지\u003c/strong>를 나타낸다.\u003c/p>\n\u003cul>\n\u003cli>always = 항상\u003c/li>\n\u003cli>usually = 보통\u003c/li>\n\u003cli>often = 자주\u003c/li>\n\u003cli>sometimes = 가끔\u003c/li>\n\u003cli>never = 절대 ~않다\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 위치\u003c/h2>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">일반동사 앞\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>usually eat\u003c/strong> breakfast at home.\u003cbr>나는 보통 집에서 아침을 먹는다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>often goes\u003c/strong> to the gym.\u003cbr>그녀는 자주 헬스장에 간다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They \u003cstrong>never drink\u003c/strong> coffee.\u003cbr>그들은 커피를 전혀 마시지 않는다.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + 빈도부사 + 일반동사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">2. 그런데 be동사에서는 위치가 달라진다\u003c/h2>\n\u003cp>be동사가 있으면 빈도부사는 보통 \u003cstrong>be동사 뒤\u003c/strong>에 온다.\u003c/p>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>usually\u003c/strong> tired after work.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>always\u003c/strong> busy.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They are \u003cstrong>often\u003c/strong> late.\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + be동사 + 빈도부사\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">3. 비교\u003c/h2>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">일반동사\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>always eats\u003c/strong> breakfast.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>always\u003c/code>가 동사 \u003ccode>eats\u003c/code> 앞.\u003c/p>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">be동사\u003c/h3>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is always\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>always\u003c/code>가 \u003ccode>is\u003c/code> 뒤.\u003c/p>\n\u003cp>이 두 개를 묶어서 외우면 된다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>일반동사 앞\u003c/strong>\u003cbr>\u003cstrong>be동사 뒤\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">4. \u003ccode>sometimes\u003c/code>는 위치가 비교적 자유롭다\u003c/h2>\n\u003cp>보통:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>sometimes eat\u003c/strong> out.\u003c/p>\n\u003c/blockquote>\n\u003cp>또는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Sometimes\u003c/strong>, I eat out.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 자연스럽다.\u003c/p>\n\u003cp>문장 끝에도 가능하다.\u003c/p>\n\u003cblockquote>\n\u003cp>I eat out \u003cstrong>sometimes\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 초반에는 가장 기본적인 형태인:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>sometimes eat\u003c/strong> out.\u003c/p>\n\u003c/blockquote>\n\u003cp>으로 익히면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. \u003ccode>never\u003c/code>는 이미 부정 의미를 가진다\u003c/h2>\n\u003cp>\u003ccode>never\u003c/code> = \u003cstrong>한 번도 ~하지 않는다\u003c/strong>\u003c/p>\n\u003cp>그래서 \u003ccode>not\u003c/code>을 또 쓰지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>✅ I never drink alcohol.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ I don&#39;t never drink alcohol.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>never\u003c/code> 자체가 이미 부정이기 때문이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. 빈도 느낌\u003c/h2>\n\u003cp>대략적인 감각은:\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>표현\u003c/th>\n\u003cth>느낌\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>always\u003c/td>\n\u003ctd>100%\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>usually\u003c/td>\n\u003ctd>대부분\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>often\u003c/td>\n\u003ctd>자주\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>sometimes\u003c/td>\n\u003ctd>가끔\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>rarely\u003c/td>\n\u003ctd>드물게\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>never\u003c/td>\n\u003ctd>0%\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>정확한 퍼센트 규칙은 아니다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">7. 의문문에서는?\u003c/h2>\n\u003cp>빈도를 물을 때는 보통:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>How often ~ ?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>를 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>How often do you exercise?\u003cbr>얼마나 자주 운동해?\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>How often does she call you?\u003cbr>그녀는 얼마나 자주 너에게 전화해?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">핵심\u003c/h2>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">일반동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>usually drink\u003c/strong> coffee.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">be동사\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am usually\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>빈도부사 = 일반동사 앞 / be동사 뒤\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">연습\u003c/h2>\n\u003cp>빈도부사의 가장 일반적인 기본 위치를 골라봐. 강조하는 문맥에서는 be동사 앞에 놓을 수도 있다.\u003c/p>\n\u003col>\n\u003cli>\u003cp>I usually drink coffee.\u003cbr>/ I drink usually coffee.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She always is busy.\u003cbr>/ She is always busy.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>He often goes to work early.\u003cbr>/ He goes often to work early.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>They never are late.\u003cbr>/ They are never late.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I sometimes eat out.\u003cbr>/ Sometimes, I eat out.\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>5번은 \u003cstrong>둘 다 맞다.\u003c/strong>\u003c/p>\n\u003cp>다음 단계는 \u003cstrong>18단계 — 과거시제(Simple Past)\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 위치","depth":2},{"id":"reading-2","label":"일반동사 앞","depth":3},{"id":"reading-3","label":"2. 그런데 be동사에서는 위치가 달라진다","depth":2},{"id":"reading-4","label":"3. 비교","depth":2},{"id":"reading-5","label":"일반동사","depth":3},{"id":"reading-6","label":"be동사","depth":3},{"id":"reading-7","label":"4. sometimes는 위치가 비교적 자유롭다","depth":2},{"id":"reading-8","label":"5. never는 이미 부정 의미를 가진다","depth":2},{"id":"reading-9","label":"6. 빈도 느낌","depth":2},{"id":"reading-10","label":"7. 의문문에서는?","depth":2},{"id":"reading-11","label":"핵심","depth":2},{"id":"reading-12","label":"일반동사","depth":3},{"id":"reading-13","label":"be동사","depth":3},{"id":"reading-14","label":"연습","depth":2}],"origin":"conversation","characters":2039,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-3","topic-3":"reading-4","topic-4":"reading-7","topic-5":"reading-8","topic-6":"reading-9","topic-7":"reading-10","topic-8":"reading-11","topic-9":"reading-14","topic-10":"concept","topic-11":"concept","topic-12":"concept"}},{"id":18,"title":"18단계 — 과거시제(Simple Past)","html":"\u003ch1 id=\"lesson-title\" data-id=\"18\">18단계 — 과거시제(Simple Past)\u003c/h1>\n\u003cp>과거시제는:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거에 일어났고 이미 끝난 일\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 말할 때 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 형태\u003c/h2>\n\u003cp>일반동사는 과거형으로 바뀐다.\u003c/p>\n\u003ch3 id=\"reading-2\" data-reading-anchor=\"reading-2\">현재\u003c/h3>\n\u003cblockquote>\n\u003cp>I work every day.\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">과거\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>worked\u003c/strong> yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>work → worked\u003c/code>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">2. 규칙동사\u003c/h2>\n\u003cp>대부분의 동사는 뒤에 \u003cstrong>-ed\u003c/strong>를 붙인다.\u003c/p>\n\u003cul>\n\u003cli>work → worked\u003c/li>\n\u003cli>play → played\u003c/li>\n\u003cli>clean → cleaned\u003c/li>\n\u003cli>watch → watched\u003c/li>\n\u003c/ul>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I worked yesterday.\u003cbr>나는 어제 일했다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She played tennis last weekend.\u003cbr>그녀는 지난 주말에 테니스를 쳤다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. 불규칙동사\u003c/h2>\n\u003cp>일부 동사는 \u003ccode>-ed\u003c/code>를 쓰지 않고 형태 자체가 변한다.\u003c/p>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>현재\u003c/th>\n\u003cth>과거\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>go\u003c/td>\n\u003ctd>went\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>eat\u003c/td>\n\u003ctd>ate\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>see\u003c/td>\n\u003ctd>saw\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>have\u003c/td>\n\u003ctd>had\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>come\u003c/td>\n\u003ctd>came\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>buy\u003c/td>\n\u003ctd>bought\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>make\u003c/td>\n\u003ctd>made\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>get\u003c/td>\n\u003ctd>got\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>이런 동사들은 별도로 익혀야 한다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>went\u003c/strong> home early.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>ate\u003c/strong> breakfast.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We \u003cstrong>bought\u003c/strong> a new car.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. 과거형에서는 주어에 따른 변화가 없다\u003c/h2>\n\u003cp>현재시제에서는:\u003c/p>\n\u003cblockquote>\n\u003cp>I work.\u003cbr>She works.\u003c/p>\n\u003c/blockquote>\n\u003cp>하지만 과거에는:\u003c/p>\n\u003cblockquote>\n\u003cp>I worked.\u003cbr>She worked.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다 같다.\u003c/p>\n\u003cp>불규칙동사도:\u003c/p>\n\u003cblockquote>\n\u003cp>I went.\u003cbr>He went.\u003cbr>They went.\u003c/p>\n\u003c/blockquote>\n\u003cp>모두 \u003ccode>went\u003c/code>.\u003c/p>\n\u003cp>즉:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>과거형은 he/she/it 때문에 -s를 붙이지 않는다.\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. 과거를 나타내는 표현\u003c/h2>\n\u003cp>과거시제와 자주 같이 나온다.\u003c/p>\n\u003cul>\n\u003cli>yesterday = 어제\u003c/li>\n\u003cli>last night = 어젯밤\u003c/li>\n\u003cli>last week = 지난주\u003c/li>\n\u003cli>last year = 작년\u003c/li>\n\u003cli>two days ago = 이틀 전\u003c/li>\n\u003cli>in 2025 = 2025년에\u003c/li>\n\u003c/ul>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I saw him yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We traveled last year.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. 부정문\u003c/h2>\n\u003cp>과거 부정문에서는 \u003cstrong>did not\u003c/strong>을 쓴다.\u003c/p>\n\u003cp>축약:\u003c/p>\n\u003cblockquote>\n\u003cp>did not → didn&#39;t\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + didn&#39;t + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I worked yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cp>부정:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>didn&#39;t work\u003c/strong> yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cp>중요하다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I didn&#39;t worked.\u003cbr>✅ I didn&#39;t work.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>did\u003c/code>가 이미 과거를 표시하기 때문에\u003cbr>뒤의 동사는 \u003cstrong>원형\u003c/strong>으로 돌아간다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. 불규칙동사도 똑같다\u003c/h2>\n\u003cp>긍정:\u003c/p>\n\u003cblockquote>\n\u003cp>She went home.\u003c/p>\n\u003c/blockquote>\n\u003cp>부정:\u003c/p>\n\u003cblockquote>\n\u003cp>She didn&#39;t go home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ She didn&#39;t went home.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>didn&#39;t\u003c/code>이 있으므로 \u003ccode>went → go\u003c/code>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">8. 의문문\u003c/h2>\n\u003cp>과거 질문은 \u003cstrong>Did\u003c/strong>를 앞에 둔다.\u003c/p>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Did + 주어 + 동사원형?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>You worked yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>Did you work yesterday?\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>She went home.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>Did she go home?\u003c/strong>\u003c/p>\n\u003cp>역시:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Did she went home?\u003cbr>✅ Did she go home?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-11\" data-reading-anchor=\"reading-11\">9. 현재와 과거 비교\u003c/h2>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">현재\u003c/h3>\n\u003cblockquote>\n\u003cp>She works here.\u003c/p>\n\u003c/blockquote>\n\u003cp>부정:\u003c/p>\n\u003cblockquote>\n\u003cp>She doesn&#39;t work here.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>Does she work here?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-13\" data-reading-anchor=\"reading-13\">과거\u003c/h3>\n\u003cblockquote>\n\u003cp>She worked here.\u003c/p>\n\u003c/blockquote>\n\u003cp>부정:\u003c/p>\n\u003cblockquote>\n\u003cp>She didn&#39;t work here.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>Did she work here?\u003c/p>\n\u003c/blockquote>\n\u003cp>과거에서는 주어가 누구든 \u003ccode>did\u003c/code>를 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">10. be동사의 과거형\u003c/h2>\n\u003cp>be동사는 일반동사와 다르다.\u003c/p>\n\u003cp>현재:\u003c/p>\n\u003cblockquote>\n\u003cp>am / is / are\u003c/p>\n\u003c/blockquote>\n\u003cp>과거:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>was / were\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-15\" data-reading-anchor=\"reading-15\">was\u003c/h3>\n\u003cblockquote>\n\u003cp>I was\u003cbr>he was\u003cbr>she was\u003cbr>it was\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-16\" data-reading-anchor=\"reading-16\">were\u003c/h3>\n\u003cblockquote>\n\u003cp>you were\u003cbr>we were\u003cbr>they were\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I was tired yesterday.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She was at home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They were busy.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">11. be동사 과거 부정문\u003c/h2>\n\u003cp>\u003ccode>not\u003c/code>만 붙인다.\u003c/p>\n\u003cblockquote>\n\u003cp>I was not tired.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She was not home.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They were not busy.\u003c/p>\n\u003c/blockquote>\n\u003cp>축약:\u003c/p>\n\u003cblockquote>\n\u003cp>wasn&#39;t\u003cbr>weren&#39;t\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">12. be동사 과거 의문문\u003c/h2>\n\u003cp>be동사를 앞으로 보낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>She was tired.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>Was she tired?\u003c/strong>\u003c/p>\n\u003cblockquote>\n\u003cp>They were busy.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ \u003cstrong>Were they busy?\u003c/strong>\u003c/p>\n\u003cp>\u003ccode>did\u003c/code>를 쓰지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Did she be tired?\u003cbr>✅ Was she tired?\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-19\" data-reading-anchor=\"reading-19\">핵심\u003c/h2>\n\u003ch3 id=\"reading-20\" data-reading-anchor=\"reading-20\">일반동사 과거\u003c/h3>\n\u003cp>긍정:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>worked\u003c/strong>.\u003cbr>I \u003cstrong>went\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>부정:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>didn&#39;t work\u003c/strong>.\u003cbr>I \u003cstrong>didn&#39;t go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>질문:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Did\u003c/strong> you \u003cstrong>work\u003c/strong>?\u003cbr>\u003cstrong>Did\u003c/strong> you \u003cstrong>go\u003c/strong>?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-21\" data-reading-anchor=\"reading-21\">be동사 과거\u003c/h3>\n\u003cblockquote>\n\u003cp>I \u003cstrong>was\u003c/strong> tired.\u003cbr>They \u003cstrong>were\u003c/strong> tired.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-22\" data-reading-anchor=\"reading-22\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I \u003cstrong>go / went\u003c/strong> home early yesterday.\u003c/li>\n\u003cli>She \u003cstrong>worked / works\u003c/strong> last weekend.\u003c/li>\n\u003cli>He \u003cstrong>didn&#39;t eat / didn&#39;t ate\u003c/strong> breakfast.\u003c/li>\n\u003cli>\u003cstrong>Did you see / Did you saw\u003c/strong> him?\u003c/li>\n\u003cli>I \u003cstrong>was / were\u003c/strong> tired yesterday.\u003c/li>\n\u003cli>They \u003cstrong>was / were\u003c/strong> at home.\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>19단계 — 미래 표현 \u003ccode>will / be going to\u003c/code>\u003c/strong>다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 형태","depth":2},{"id":"reading-2","label":"현재","depth":3},{"id":"reading-3","label":"과거","depth":3},{"id":"reading-4","label":"2. 규칙동사","depth":2},{"id":"reading-5","label":"3. 불규칙동사","depth":2},{"id":"reading-6","label":"4. 과거형에서는 주어에 따른 변화가 없다","depth":2},{"id":"reading-7","label":"5. 과거를 나타내는 표현","depth":2},{"id":"reading-8","label":"6. 부정문","depth":2},{"id":"reading-9","label":"7. 불규칙동사도 똑같다","depth":2},{"id":"reading-10","label":"8. 의문문","depth":2},{"id":"reading-11","label":"9. 현재와 과거 비교","depth":2},{"id":"reading-12","label":"현재","depth":3},{"id":"reading-13","label":"과거","depth":3},{"id":"reading-14","label":"10. be동사의 과거형","depth":2},{"id":"reading-15","label":"was","depth":3},{"id":"reading-16","label":"were","depth":3},{"id":"reading-17","label":"11. be동사 과거 부정문","depth":2},{"id":"reading-18","label":"12. be동사 과거 의문문","depth":2},{"id":"reading-19","label":"핵심","depth":2},{"id":"reading-20","label":"일반동사 과거","depth":3},{"id":"reading-21","label":"be동사 과거","depth":3},{"id":"reading-22","label":"연습","depth":2}],"origin":"conversation","characters":3047,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-11","topic-1":"reading-1","topic-2":"reading-4","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-11","topic-10":"reading-14","topic-11":"reading-17","topic-12":"reading-18"}},{"id":19,"title":"19단계 — 미래 표현 will / be going to","html":"\u003ch1 id=\"lesson-title\" data-id=\"19\">19단계 — 미래 표현 \u003ccode>will / be going to\u003c/code>\u003c/h1>\n\u003cp>영어에는 미래만을 위한 별도의 동사형이 없다.\u003cbr>대신 \u003cstrong>미래를 나타내는 표현\u003c/strong>을 사용한다.\u003c/p>\n\u003cp>가장 기본적인 두 가지가:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>will + 동사원형\u003c/strong>\u003cbr>\u003cstrong>be going to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. \u003ccode>will\u003c/code>\u003c/h2>\n\u003cp>기본 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + will + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>will go\u003c/strong> home.\u003cbr>나는 집에 갈 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>will call\u003c/strong> you.\u003cbr>그녀는 너에게 전화할 것이다.\u003c/p>\n\u003c/blockquote>\n\u003cp>주어가 바뀌어도 \u003ccode>will\u003c/code>은 그대로다.\u003c/p>\n\u003cblockquote>\n\u003cp>I will go.\u003cbr>He will go.\u003cbr>They will go.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. \u003ccode>will\u003c/code>의 기본 의미\u003c/h2>\n\u003cp>초급 단계에서는 크게 두 가지로 잡으면 된다.\u003c/p>\n\u003ch3 id=\"reading-3\" data-reading-anchor=\"reading-3\">① 지금 결정한 일\u003c/h3>\n\u003cblockquote>\n\u003cp>I&#39;m tired.\u003cbr>I \u003cstrong>will go\u003c/strong> home now.\u003c/p>\n\u003c/blockquote>\n\u003cp>지금 상황을 보고:\u003c/p>\n\u003cblockquote>\n\u003cp>&quot;그럼 집에 가야겠다.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>라고 결정한 느낌이다.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-4\" data-reading-anchor=\"reading-4\">② 미래에 대한 예상\u003c/h3>\n\u003cblockquote>\n\u003cp>I think it \u003cstrong>will rain\u003c/strong> tomorrow.\u003cbr>내일 비가 올 것 같아.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>will like\u003c/strong> it.\u003cbr>그녀는 그걸 좋아할 거야.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-5\" data-reading-anchor=\"reading-5\">3. \u003ccode>will\u003c/code>의 부정문\u003c/h2>\n\u003cblockquote>\n\u003cp>will not\u003c/p>\n\u003c/blockquote>\n\u003cp>축약:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>won&#39;t\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>won&#39;t go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>won&#39;t come\u003c/strong> tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cp>중요:\u003c/p>\n\u003cblockquote>\n\u003cp>✅ won&#39;t go\u003cbr>❌ won&#39;t goes\u003cbr>❌ won&#39;t went\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003ccode>will\u003c/code> 뒤에는 항상 \u003cstrong>동사원형\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-6\" data-reading-anchor=\"reading-6\">4. \u003ccode>will\u003c/code>의 의문문\u003c/h2>\n\u003cp>\u003ccode>will\u003c/code>을 주어 앞으로 보낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>You will come.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Will you come?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She will call me.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Will she call me?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Will + 주어 + 동사원형?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">5. \u003ccode>be going to\u003c/code>\u003c/h2>\n\u003cp>기본 구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + am/is/are + going to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am going to travel\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is going to study\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They \u003cstrong>are going to move\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>여기서 중요한 점:\u003c/p>\n\u003cp>\u003ccode>going to\u003c/code> 앞의 \u003ccode>be동사\u003c/code>가 주어에 따라 바뀐다.\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am\u003c/strong> going to\u003cbr>He/She/It \u003cstrong>is\u003c/strong> going to\u003cbr>You/We/They \u003cstrong>are\u003c/strong> going to\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">6. \u003ccode>be going to\u003c/code>의 기본 의미\u003c/h2>\n\u003cp>주로 \u003cstrong>이미 계획하거나 마음먹은 미래\u003c/strong>를 말한다.\u003c/p>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>going to visit\u003c/strong> Taiwan next month.\u003c/p>\n\u003c/blockquote>\n\u003cp>이미 여행 계획이 있는 상태.\u003c/p>\n\u003cblockquote>\n\u003cp>We&#39;re \u003cstrong>going to buy\u003c/strong> a new car.\u003c/p>\n\u003c/blockquote>\n\u003cp>차를 살 계획이 이미 있다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">7. \u003ccode>will\u003c/code>과 \u003ccode>be going to\u003c/code> 비교\u003c/h2>\n\u003cp>상황을 보자.\u003c/p>\n\u003cp>친구가 말한다.\u003c/p>\n\u003cblockquote>\n\u003cp>&quot;It&#39;s cold.&quot;\u003c/p>\n\u003c/blockquote>\n\u003cp>그 말을 듣고 지금 결정:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>will close\u003c/strong> the window.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 지금 결정\u003c/p>\n\u003chr>\n\u003cp>반면 아침부터 창문을 닫으려고 생각하고 있었다면:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m \u003cstrong>going to close\u003c/strong> the window.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 이미 하려고 계획함\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-10\" data-reading-anchor=\"reading-10\">기본 감각\u003c/h2>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">\u003ccode>will\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>지금 결정 / 단순한 예상\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">\u003ccode>be going to\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>이미 계획된 미래\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이 정도 구분부터 잡으면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">8. 실제 회화에서는 겹치는 경우도 많다\u003c/h2>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;ll call you tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;m going to call you tomorrow.\u003c/p>\n\u003c/blockquote>\n\u003cp>둘 다:\u003c/p>\n\u003cblockquote>\n\u003cp>내일 전화할게.\u003c/p>\n\u003c/blockquote>\n\u003cp>가 될 수 있다.\u003c/p>\n\u003cp>차이는 뉘앙스다.\u003c/p>\n\u003cul>\n\u003cli>\u003ccode>I&#39;ll call you.\u003c/code> → 지금 약속하거나 결정하는 느낌\u003c/li>\n\u003cli>\u003ccode>I&#39;m going to call you.\u003c/code> → 이미 그럴 계획이 있다는 느낌\u003c/li>\n\u003c/ul>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">9. \u003ccode>be going to\u003c/code>의 부정문\u003c/h2>\n\u003cp>be동사 뒤에 \u003ccode>not\u003c/code>\u003c/p>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>not going to go\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>not going to come\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They are \u003cstrong>not going to buy\u003c/strong> it.\u003c/p>\n\u003c/blockquote>\n\u003cp>축약하면:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m not going to go.\u003cbr>She isn&#39;t going to come.\u003cbr>They aren&#39;t going to buy it.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">10. \u003ccode>be going to\u003c/code>의 의문문\u003c/h2>\n\u003cp>be동사를 앞으로 보낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>You are going to travel.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Are you going to travel?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is going to come.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Is she going to come?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">핵심\u003c/h2>\n\u003ch3 id=\"reading-17\" data-reading-anchor=\"reading-17\">\u003ccode>will\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>will + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I will go.\u003cbr>I won&#39;t go.\u003cbr>Will you go?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-18\" data-reading-anchor=\"reading-18\">\u003ccode>be going to\u003c/code>\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>am/is/are + going to + 동사원형\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I&#39;m going to go.\u003cbr>I&#39;m not going to go.\u003cbr>Are you going to go?\u003c/p>\n\u003c/blockquote>\n\u003ch3 id=\"reading-19\" data-reading-anchor=\"reading-19\">기본 차이\u003c/h3>\n\u003cblockquote>\n\u003cp>\u003cstrong>will = 지금 결정 / 예상\u003c/strong>\u003cbr>\u003cstrong>be going to = 이미 있는 계획\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-20\" data-reading-anchor=\"reading-20\">연습\u003c/h2>\n\u003cp>더 자연스러운 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>\u003cp>전화벨이 울린다.\u003cbr>&quot;내가 받을게.&quot;\u003cbr>→ I \u003cstrong>will answer / am going to answer\u003c/strong> it.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>다음 달 대만여행을 이미 예약했다.\u003cbr>→ We \u003cstrong>will travel / are going to travel\u003c/strong> to Taiwan next month.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>I think it \u003cstrong>will rain / is going to rain\u003c/strong> tomorrow.\u003cbr>→ 단순한 예상\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>She \u003cstrong>won&#39;t comes / won&#39;t come\u003c/strong>.\u003c/p>\n\u003c/li>\n\u003cli>\u003cp>\u003cstrong>Will you go / Will you went\u003c/strong> with me?\u003c/p>\n\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>20단계 — 현재진행형 \u003ccode>am/is/are + -ing\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. will","depth":2},{"id":"reading-2","label":"2. will의 기본 의미","depth":2},{"id":"reading-3","label":"① 지금 결정한 일","depth":3},{"id":"reading-4","label":"② 미래에 대한 예상","depth":3},{"id":"reading-5","label":"3. will의 부정문","depth":2},{"id":"reading-6","label":"4. will의 의문문","depth":2},{"id":"reading-7","label":"5. be going to","depth":2},{"id":"reading-8","label":"6. be going to의 기본 의미","depth":2},{"id":"reading-9","label":"7. will과 be going to 비교","depth":2},{"id":"reading-10","label":"기본 감각","depth":2},{"id":"reading-11","label":"will","depth":3},{"id":"reading-12","label":"be going to","depth":3},{"id":"reading-13","label":"8. 실제 회화에서는 겹치는 경우도 많다","depth":2},{"id":"reading-14","label":"9. be going to의 부정문","depth":2},{"id":"reading-15","label":"10. be going to의 의문문","depth":2},{"id":"reading-16","label":"핵심","depth":2},{"id":"reading-17","label":"will","depth":3},{"id":"reading-18","label":"be going to","depth":3},{"id":"reading-19","label":"기본 차이","depth":3},{"id":"reading-20","label":"연습","depth":2}],"origin":"conversation","characters":3111,"aliases":{"structure":"concept","examples":"concept","contrast":"reading-9","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-5","topic-4":"reading-6","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-10","topic-9":"reading-13","topic-10":"reading-14","topic-11":"reading-15","topic-12":"reading-16"}},{"id":20,"title":"20단계 — 현재진행형 be + -ing","html":"\u003ch1 id=\"lesson-title\" data-id=\"20\">20단계 — 현재진행형 \u003ccode>be + -ing\u003c/code>\u003c/h1>\n\u003cp>현재진행형은 기본적으로:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>지금 진행 중인 행동\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>을 말할 때 쓴다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-1\" data-reading-anchor=\"reading-1\">1. 기본 구조\u003c/h2>\n\u003cblockquote>\n\u003cp>\u003cstrong>주어 + am/is/are + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I \u003cstrong>am eating\u003c/strong>.\u003cbr>나는 지금 먹고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She \u003cstrong>is sleeping\u003c/strong>.\u003cbr>그녀는 지금 자고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They \u003cstrong>are working\u003c/strong>.\u003cbr>그들은 지금 일하고 있다.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-2\" data-reading-anchor=\"reading-2\">2. 왜 be동사가 필요한가?\u003c/h2>\n\u003cp>현재진행형은:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003ccode>동사-ing\u003c/code>만 쓰는 구조가 아니다.\u003c/p>\n\u003c/blockquote>\n\u003cp>반드시:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be동사 + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>가 한 묶음이다.\u003c/p>\n\u003cp>그래서:\u003c/p>\n\u003cblockquote>\n\u003cp>❌ I eating.\u003cbr>✅ I am eating.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>❌ She working.\u003cbr>✅ She is working.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-3\" data-reading-anchor=\"reading-3\">3. 주어에 따른 형태\u003c/h2>\n\u003cdiv class=\"table-scroll\" role=\"region\" aria-label=\"문법 비교 표\" tabindex=\"0\">\u003ctable>\n\u003cthead>\n\u003ctr>\n\u003cth>주어\u003c/th>\n\u003cth>현재진행형\u003c/th>\n\u003c/tr>\n\u003c/thead>\n\u003ctbody>\u003ctr>\n\u003ctd>I\u003c/td>\n\u003ctd>am working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>you\u003c/td>\n\u003ctd>are working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>he\u003c/td>\n\u003ctd>is working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>she\u003c/td>\n\u003ctd>is working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>it\u003c/td>\n\u003ctd>is working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>we\u003c/td>\n\u003ctd>are working\u003c/td>\n\u003c/tr>\n\u003ctr>\n\u003ctd>they\u003c/td>\n\u003ctd>are working\u003c/td>\n\u003c/tr>\n\u003c/tbody>\u003c/table>\n\u003c/div>\u003cp>즉, \u003ccode>working\u003c/code>은 그대로이고\u003cbr>앞의 \u003cstrong>be동사만 주어에 따라 바뀐다.\u003c/strong>\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-4\" data-reading-anchor=\"reading-4\">4. 현재시제와 차이\u003c/h2>\n\u003cp>이 차이가 핵심이다.\u003c/p>\n\u003ch3 id=\"reading-5\" data-reading-anchor=\"reading-5\">현재시제\u003c/h3>\n\u003cblockquote>\n\u003cp>I work at a construction company.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 건설회사에서 일한다.\u003c/p>\n\u003c/blockquote>\n\u003cp>평소 직업이나 일반적인 사실.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-6\" data-reading-anchor=\"reading-6\">현재진행형\u003c/h3>\n\u003cblockquote>\n\u003cp>I am working now.\u003c/p>\n\u003c/blockquote>\n\u003cp>뜻:\u003c/p>\n\u003cblockquote>\n\u003cp>나는 지금 일하고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>\u003cstrong>현재 이 순간 진행 중\u003c/strong>이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-7\" data-reading-anchor=\"reading-7\">비교\u003c/h2>\n\u003cblockquote>\n\u003cp>She drinks coffee every morning.\u003cbr>그녀는 매일 아침 커피를 마신다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 습관\u003c/p>\n\u003cblockquote>\n\u003cp>She is drinking coffee now.\u003cbr>그녀는 지금 커피를 마시고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>→ 지금 진행 중\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-8\" data-reading-anchor=\"reading-8\">5. 지금만 잠시 그런 상황\u003c/h2>\n\u003cp>현재진행형은 꼭 바로 이 순간만 뜻하지는 않는다.\u003c/p>\n\u003cp>\u003cstrong>요즘 일시적으로 진행되는 상황\u003c/strong>에도 쓴다.\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m studying English these days.\u003cbr>나는 요즘 영어를 공부하고 있다.\u003c/p>\n\u003c/blockquote>\n\u003cp>지금 말하는 순간에 영어책을 보고 있다는 뜻은 아니다.\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>요즘 계속 진행 중인 일\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>이라는 뜻이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-9\" data-reading-anchor=\"reading-9\">6. \u003ccode>-ing\u003c/code> 만드는 기본 규칙\u003c/h2>\n\u003ch3 id=\"reading-10\" data-reading-anchor=\"reading-10\">대부분\u003c/h3>\n\u003cblockquote>\n\u003cp>work → working\u003cbr>eat → eating\u003cbr>play → playing\u003c/p>\n\u003c/blockquote>\n\u003cp>그냥 \u003ccode>-ing\u003c/code>.\u003c/p>\n\u003chr>\n\u003ch3 id=\"reading-11\" data-reading-anchor=\"reading-11\">\u003ccode>e\u003c/code>로 끝나면 보통 \u003ccode>e\u003c/code>를 빼고\u003c/h3>\n\u003cblockquote>\n\u003cp>make → making\u003cbr>come → coming\u003cbr>write → writing\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch3 id=\"reading-12\" data-reading-anchor=\"reading-12\">짧은 단어에서 마지막 자음을 한 번 더 쓰는 경우\u003c/h3>\n\u003cblockquote>\n\u003cp>run → running\u003cbr>sit → sitting\u003cbr>swim → swimming\u003c/p>\n\u003c/blockquote>\n\u003cp>지금은 대표적인 형태부터 익히면 된다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-13\" data-reading-anchor=\"reading-13\">7. 부정문\u003c/h2>\n\u003cp>be동사 뒤에 \u003ccode>not\u003c/code>.\u003c/p>\n\u003cblockquote>\n\u003cp>I am \u003cstrong>not working\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is \u003cstrong>not sleeping\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>They are \u003cstrong>not eating\u003c/strong>.\u003c/p>\n\u003c/blockquote>\n\u003cp>축약:\u003c/p>\n\u003cblockquote>\n\u003cp>She isn&#39;t sleeping.\u003cbr>They aren&#39;t eating.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-14\" data-reading-anchor=\"reading-14\">8. 의문문\u003c/h2>\n\u003cp>be동사를 앞으로 보낸다.\u003c/p>\n\u003cblockquote>\n\u003cp>You are working.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Are you working?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She is sleeping.\u003c/p>\n\u003c/blockquote>\n\u003cp>→\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Is she sleeping?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>구조:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>Am/Is/Are + 주어 + 동사-ing?\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-15\" data-reading-anchor=\"reading-15\">9. 일반동사 의문문과 비교\u003c/h2>\n\u003cp>현재시제:\u003c/p>\n\u003cblockquote>\n\u003cp>Do you work here?\u003c/p>\n\u003c/blockquote>\n\u003cp>현재진행형:\u003c/p>\n\u003cblockquote>\n\u003cp>Are you working now?\u003c/p>\n\u003c/blockquote>\n\u003cp>현재진행형에서는 \u003ccode>do\u003c/code>를 쓰지 않는다.\u003c/p>\n\u003cblockquote>\n\u003cp>❌ Do you working?\u003cbr>✅ Are you working?\u003c/p>\n\u003c/blockquote>\n\u003cp>왜냐하면 이미 \u003ccode>are\u003c/code>라는 be동사가 있기 때문이다.\u003c/p>\n\u003chr>\n\u003ch2 id=\"reading-16\" data-reading-anchor=\"reading-16\">10. 자주 같이 쓰는 표현\u003c/h2>\n\u003cp>현재진행형과 잘 어울린다.\u003c/p>\n\u003cul>\n\u003cli>now = 지금\u003c/li>\n\u003cli>right now = 바로 지금\u003c/li>\n\u003cli>at the moment = 지금 이 순간\u003c/li>\n\u003cli>these days = 요즘\u003c/li>\n\u003c/ul>\n\u003cp>예:\u003c/p>\n\u003cblockquote>\n\u003cp>I&#39;m eating now.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>She&#39;s working at the moment.\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>We&#39;re learning English these days.\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-17\" data-reading-anchor=\"reading-17\">핵심\u003c/h2>\n\u003cp>현재진행형:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>be동사 + 동사-ing\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>의미:\u003c/p>\n\u003cblockquote>\n\u003cp>\u003cstrong>지금 또는 요즘 진행 중인 행동\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cp>비교:\u003c/p>\n\u003cblockquote>\n\u003cp>I work every day.\u003cbr>\u003cstrong>평소\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003cblockquote>\n\u003cp>I am working now.\u003cbr>\u003cstrong>지금\u003c/strong>\u003c/p>\n\u003c/blockquote>\n\u003chr>\n\u003ch2 id=\"reading-18\" data-reading-anchor=\"reading-18\">연습\u003c/h2>\n\u003cp>맞는 것을 골라봐.\u003c/p>\n\u003col>\n\u003cli>I \u003cstrong>am eating / eat\u003c/strong> right now.\u003c/li>\n\u003cli>She \u003cstrong>is sleep / is sleeping\u003c/strong> now.\u003c/li>\n\u003cli>They \u003cstrong>are working / working\u003c/strong> at the moment.\u003c/li>\n\u003cli>\u003cstrong>Do you working / Are you working\u003c/strong> now?\u003c/li>\n\u003cli>He \u003cstrong>doesn&#39;t sleeping / isn&#39;t sleeping\u003c/strong>.\u003c/li>\n\u003cli>I \u003cstrong>study / am studying\u003c/strong> English every day.\u003cbr>→ 매일 하는 습관\u003c/li>\n\u003c/ol>\n\u003cp>다음 단계는 \u003cstrong>21단계 — 과거진행형 \u003ccode>was/were + -ing\u003c/code>\u003c/strong>이다.\u003c/p>\n","toc":[{"id":"reading-1","label":"1. 기본 구조","depth":2},{"id":"reading-2","label":"2. 왜 be동사가 필요한가?","depth":2},{"id":"reading-3","label":"3. 주어에 따른 형태","depth":2},{"id":"reading-4","label":"4. 현재시제와 차이","depth":2},{"id":"reading-5","label":"현재시제","depth":3},{"id":"reading-6","label":"현재진행형","depth":3},{"id":"reading-7","label":"비교","depth":2},{"id":"reading-8","label":"5. 지금만 잠시 그런 상황","depth":2},{"id":"reading-9","label":"6. -ing 만드는 기본 규칙","depth":2},{"id":"reading-10","label":"대부분","depth":3},{"id":"reading-11","label":"e로 끝나면 보통 e를 빼고","depth":3},{"id":"reading-12","label":"짧은 단어에서 마지막 자음을 한 번 더 쓰는 경우","depth":3},{"id":"reading-13","label":"7. 부정문","depth":2},{"id":"reading-14","label":"8. 의문문","depth":2},{"id":"reading-15","label":"9. 일반동사 의문문과 비교","depth":2},{"id":"reading-16","label":"10. 자주 같이 쓰는 표현","depth":2},{"id":"reading-17","label":"핵심","depth":2},{"id":"reading-18","label":"연습","depth":2}],"origin":"conversation","characters":2722,"aliases":{"structure":"reading-1","examples":"concept","contrast":"reading-4","topic-1":"reading-1","topic-2":"reading-2","topic-3":"reading-3","topic-4":"reading-4","topic-5":"reading-7","topic-6":"reading-8","topic-7":"reading-9","topic-8":"reading-13","topic-9":"reading-14","topic-10":"reading-15","topic-11":"reading-16","topic-12":"reading-17"}}]);
